INSERT INTO `modules`(id,language,title,level,summary) SELECT n.id,n.language,n.title,n.level,n.summary FROM `new_modules` n WHERE NOT EXISTS (SELECT 1 FROM `modules`);
INSERT INTO `new_lessons`(id,module_id,position,title,body) VALUES
(22,9,1,'Hello world with print','print() shows text on the screen. Text goes inside quotes.\n```\nprint("Hello, world!")\n```\nOutput:\n```\nHello, world!\n```\nTry it: change the values in the playground and run it again.'),
(23,9,2,'Comments','A comment starts with # and is ignored by Python. Use comments to explain your code.\n```\n# This line is ignored\nprint("Comments help people")  # so does this part\n```\nOutput:\n```\nComments help people\n```\nTry it: change the values in the playground and run it again.'),
(24,9,3,'Variables','A variable is a name that stores a value. Use = to store it.\n```\nage = 18\nname = "Ana"\nprint(name, age)\n```\nOutput:\n```\nAna 18\n```\nTry it: change the values in the playground and run it again.'),
(25,9,4,'Naming variables','Variable names use letters, digits and underscores and cannot start with a digit. Choose clear lowercase names like total_price.\n```\ntotal_price = 250\nitem_count = 3\nprint(total_price * item_count)\n```\nOutput:\n```\n750\n```\nTry it: change the values in the playground and run it again.'),
(26,9,5,'Numbers','Python has whole numbers (int) and decimal numbers (float).\n```\na = 7\nb = 2.5\nprint(a + b)\nprint(type(a), type(b))\n```\nOutput:\n```\n9.5\n<class \'int\'> <class \'float\'>\n```\nTry it: change the values in the playground and run it again.'),
(27,9,6,'Math operators','Use + - * / for math and ** for powers. Brackets change the order.\n```\nprint(2 + 3 * 4)\nprint((2 + 3) * 4)\nprint(2 ** 5)\nprint(7 / 2)\n```\nOutput:\n```\n14\n20\n32\n3.5\n```\nTry it: change the values in the playground and run it again.'),
(28,9,7,'Integer division and remainder','// gives the whole-number part of a division and % gives the remainder.\n```\nprint(17 // 5)\nprint(17 % 5)\nprint(10 % 2 == 0)\n```\nOutput:\n```\n3\n2\nTrue\n```\nTry it: change the values in the playground and run it again.'),
(29,9,8,'Strings','A string is text. Each character has a position that starts at 0.\n```\nword = "Python"\nprint(word)\nprint(len(word))\nprint(word[0])\n```\nOutput:\n```\nPython\n6\nP\n```\nTry it: change the values in the playground and run it again.'),
(30,9,9,'String concatenation','Join strings with +. Numbers must be converted with str() first.\n```\nfirst = "Code"\nsecond = "Smart"\nprint(first + second)\nprint("Level " + str(3))\n```\nOutput:\n```\nCodeSmart\nLevel 3\n```\nTry it: change the values in the playground and run it again.'),
(31,9,10,'String repetition','Multiply a string by a whole number to repeat it.\n```\nprint("ha" * 3)\nprint("-" * 20)\n```\nOutput:\n```\nhahaha\n--------------------\n```\nTry it: change the values in the playground and run it again.'),
(32,9,11,'f-strings','An f-string puts values inside text. Write f before the quote and put variables in braces.\n```\nname = "Ana"\nscore = 95\nprint(f"{name} scored {score} points")\n```\nOutput:\n```\nAna scored 95 points\n```\nTry it: change the values in the playground and run it again.'),
(33,9,12,'Input from the user','input() pauses and asks the user to type, and it always returns text. The playground cannot ask for typing, so here we pretend the user typed Ana.\n```\n# name = input("Your name? ")\nname = "Ana"\nprint("Hello,", name)\n```\nOutput:\n```\nHello, Ana\n```\nTry it: change the values in the playground and run it again.'),
(34,9,13,'Type conversion','int(), float() and str() convert between types.\n```\ntext = "42"\nnumber = int(text)\nprint(number + 8)\nprint(float("3.5") * 2)\nprint(str(10) + "!")\n```\nOutput:\n```\n50\n7.0\n10!\n```\nTry it: change the values in the playground and run it again.'),
(35,9,14,'Booleans','A boolean is either True or False. Comparisons produce booleans.\n```\nis_open = True\nprint(is_open)\nprint(5 > 3)\nprint(type(False))\n```\nOutput:\n```\nTrue\nTrue\n<class \'bool\'>\n```\nTry it: change the values in the playground and run it again.'),
(36,9,15,'Comparison operators','Comparison operators are == != < > <= >=. Use == to compare and = to store.\n```\nprint(5 == 5)\nprint(5 != 3)\nprint(4 >= 9)\nprint("a" < "b")\n```\nOutput:\n```\nTrue\nTrue\nFalse\nTrue\n```\nTry it: change the values in the playground and run it again.'),
(37,9,16,'Logical operators','and needs both sides True, or needs one side True, and not flips a value.\n```\nage = 20\nprint(age > 18 and age < 30)\nprint(age < 10 or age > 15)\nprint(not age > 18)\n```\nOutput:\n```\nTrue\nTrue\nFalse\n```\nTry it: change the values in the playground and run it again.'),
(38,9,17,'if statements','An if statement runs code only when its condition is True. The indented lines belong to the if.\n```\ntemp = 32\nif temp > 30:\n    print("It is hot")\nprint("Done")\n```\nOutput:\n```\nIt is hot\nDone\n```\nTry it: change the values in the playground and run it again.'),
(39,9,18,'else and elif','else runs when the if is False. elif tests another condition in between.\n```\nscore = 75\nif score >= 90:\n    print("A")\nelif score >= 70:\n    print("B")\nelse:\n    print("Try again")\n```\nOutput:\n```\nB\n```\nTry it: change the values in the playground and run it again.'),
(40,9,19,'Nested conditions','You can put an if inside another if.\n```\nage = 20\nhas_id = True\nif age >= 18:\n    if has_id:\n        print("Welcome in")\n    else:\n        print("Show your ID")\n```\nOutput:\n```\nWelcome in\n```\nTry it: change the values in the playground and run it again.'),
(41,9,20,'Truthy and falsy values','Zero, empty text, empty lists and None count as False. Everything else counts as True.\n```\nprint(bool(0))\nprint(bool(""))\nprint(bool([]))\nprint(bool("hi"))\nprint(bool(5))\n```\nOutput:\n```\nFalse\nFalse\nFalse\nTrue\nTrue\n```\nTry it: change the values in the playground and run it again.'),
(42,9,21,'while loops','A while loop repeats while its condition is True. Change something inside so it can stop.\n```\ncount = 1\nwhile count <= 3:\n    print("Round", count)\n    count += 1\n```\nOutput:\n```\nRound 1\nRound 2\nRound 3\n```\nTry it: change the values in the playground and run it again.'),
(43,9,22,'for loops','A for loop goes through the items of a sequence one by one.\n```\nfor fruit in ["apple", "mango", "kiwi"]:\n    print(fruit)\n```\nOutput:\n```\napple\nmango\nkiwi\n```\nTry it: change the values in the playground and run it again.'),
(44,9,23,'range()','range(start, stop) makes numbers from start up to but not including stop. range(3) starts at 0.\n```\nfor i in range(3):\n    print(i)\nprint(list(range(2, 10, 3)))\n```\nOutput:\n```\n0\n1\n2\n[2, 5, 8]\n```\nTry it: change the values in the playground and run it again.'),
(45,9,24,'break and continue','break leaves a loop early. continue skips to the next round.\n```\nfor n in range(1, 8):\n    if n == 3:\n        continue\n    if n == 6:\n        break\n    print(n)\n```\nOutput:\n```\n1\n2\n4\n5\n```\nTry it: change the values in the playground and run it again.'),
(46,9,25,'Loop with else','A loop else runs only when the loop finishes without break.\n```\nfor n in [1, 3, 5]:\n    if n % 2 == 0:\n        print("found even")\n        break\nelse:\n    print("no even number")\n```\nOutput:\n```\nno even number\n```\nTry it: change the values in the playground and run it again.'),
(47,9,26,'Lists','A list holds many values in order, written in square brackets.\n```\ncolors = ["red", "green", "blue"]\nprint(colors)\nprint(len(colors))\n```\nOutput:\n```\n[\'red\', \'green\', \'blue\']\n3\n```\nTry it: change the values in the playground and run it again.'),
(48,9,27,'List indexing','Positions start at 0. Negative positions count from the end.\n```\ncolors = ["red", "green", "blue"]\nprint(colors[0])\nprint(colors[2])\nprint(colors[-1])\n```\nOutput:\n```\nred\nblue\nblue\n```\nTry it: change the values in the playground and run it again.'),
(49,9,28,'List slicing','A slice list[start:stop] copies part of a list. The stop position is not included.\n```\nnums = [10, 20, 30, 40, 50]\nprint(nums[1:4])\nprint(nums[:2])\nprint(nums[::2])\n```\nOutput:\n```\n[20, 30, 40]\n[10, 20]\n[10, 30, 50]\n```\nTry it: change the values in the playground and run it again.'),
(50,9,29,'Changing lists','Lists can change. Assign to a position to replace an item and use del to remove one.\n```\nnums = [1, 2, 3]\nnums[0] = 99\nprint(nums)\ndel nums[1]\nprint(nums)\n```\nOutput:\n```\n[99, 2, 3]\n[99, 3]\n```\nTry it: change the values in the playground and run it again.'),
(51,9,30,'List methods','Common list methods are append, insert, remove, pop, sort and reverse.\n```\nnums = [3, 1, 2]\nnums.append(5)\nnums.sort()\nprint(nums)\nprint(nums.pop())\nprint(nums)\n```\nOutput:\n```\n[1, 2, 3, 5]\n5\n[1, 2, 3]\n```\nTry it: change the values in the playground and run it again.'),
(52,9,31,'Tuples','A tuple is like a list that cannot change. It uses round brackets.\n```\npoint = (4, 7)\nprint(point[0])\nx, y = point\nprint(x + y)\n```\nOutput:\n```\n4\n11\n```\nTry it: change the values in the playground and run it again.'),
(53,9,32,'Sets','A set keeps only unique items and has no fixed order.\n```\ntags = {"a", "b", "a", "c"}\nprint(len(tags))\ntags.add("d")\nprint(sorted(tags))\n```\nOutput:\n```\n3\n[\'a\', \'b\', \'c\', \'d\']\n```\nTry it: change the values in the playground and run it again.'),
(54,9,33,'Dictionaries','A dictionary stores key and value pairs.\n```\nstudent = {"name": "Ana", "age": 20}\nprint(student["name"])\nstudent["age"] = 21\nprint(student)\n```\nOutput:\n```\nAna\n{\'name\': \'Ana\', \'age\': 21}\n```\nTry it: change the values in the playground and run it again.'),
(55,9,34,'Dictionary methods','Useful dictionary methods are get, keys, values and items.\n```\nd = {"a": 1, "b": 2}\nprint(d.get("c", 0))\nprint(list(d.keys()))\nprint(list(d.values()))\nfor k, v in d.items():\n    print(k, v)\n```\nOutput:\n```\n0\n[\'a\', \'b\']\n[1, 2]\na 1\nb 2\n```\nTry it: change the values in the playground and run it again.'),
(56,9,35,'len() and type()','len() counts items. type() tells you what kind of value you have.\n```\nprint(len("hello"))\nprint(len([1, 2, 3]))\nprint(type(3.5))\nprint(type("hi"))\n```\nOutput:\n```\n5\n3\n<class \'float\'>\n<class \'str\'>\n```\nTry it: change the values in the playground and run it again.'),
(57,9,36,'min max and sum','min(), max() and sum() work on lists of numbers.\n```\nnums = [4, 9, 2]\nprint(min(nums))\nprint(max(nums))\nprint(sum(nums))\n```\nOutput:\n```\n2\n9\n15\n```\nTry it: change the values in the playground and run it again.'),
(58,9,37,'Round and abs','round() rounds a number and abs() removes a minus sign.\n```\nprint(round(3.14159, 2))\nprint(round(7.6))\nprint(abs(-8))\n```\nOutput:\n```\n3.14\n8\n8\n```\nTry it: change the values in the playground and run it again.'),
(59,9,38,'String methods','Strings have methods such as upper, title and count.\n```\ns = "hello world"\nprint(s.upper())\nprint(s.title())\nprint(s.count("o"))\n```\nOutput:\n```\nHELLO WORLD\nHello World\n2\n```\nTry it: change the values in the playground and run it again.'),
(60,9,39,'Splitting and joining','split() breaks text into a list and join() glues a list back into text.\n```\nwords = "red,green,blue".split(",")\nprint(words)\nprint(" - ".join(words))\n```\nOutput:\n```\n[\'red\', \'green\', \'blue\']\nred - green - blue\n```\nTry it: change the values in the playground and run it again.'),
(61,9,40,'Strip and replace','strip() removes spaces at both ends and replace() swaps text.\n```\ns = "  hi there  "\nprint(s.strip())\nprint(s.replace("hi", "hello"))\n```\nOutput:\n```\nhi there\n  hello there\n```\nTry it: change the values in the playground and run it again.');
INSERT INTO `new_lessons`(id,module_id,position,title,body) VALUES
(62,9,41,'Checking membership','in checks whether a value is inside a list, string or dictionary.\n```\nprint("a" in "banana")\nprint(3 in [1, 2, 3])\nprint("x" not in "abc")\n```\nOutput:\n```\nTrue\nTrue\nTrue\n```\nTry it: change the values in the playground and run it again.'),
(63,9,42,'enumerate()','enumerate() gives the position and the item together.\n```\nfor i, name in enumerate(["Ana", "Ben", "Cy"], start=1):\n    print(i, name)\n```\nOutput:\n```\n1 Ana\n2 Ben\n3 Cy\n```\nTry it: change the values in the playground and run it again.'),
(64,9,43,'Nested loops','A loop inside a loop runs the inner loop fully for each round of the outer loop.\n```\nfor row in range(1, 4):\n    for col in range(1, 4):\n        print(row * col, end=" ")\n    print()\n```\nOutput:\n```\n1 2 3 \n2 4 6 \n3 6 9\n```\nTry it: change the values in the playground and run it again.'),
(65,9,44,'Counting with loops','Use a counter variable to count the items that match a test.\n```\ncount = 0\nfor n in range(1, 21):\n    if n % 3 == 0:\n        count += 1\nprint(count)\n```\nOutput:\n```\n6\n```\nTry it: change the values in the playground and run it again.'),
(66,9,45,'Accumulator pattern','An accumulator starts at zero or empty and grows each round.\n```\ntotal = 0\nfor price in [5, 10, 20]:\n    total += price\nprint(total)\nword = ""\nfor ch in "abc":\n    word += ch.upper()\nprint(word)\n```\nOutput:\n```\n35\nABC\n```\nTry it: change the values in the playground and run it again.'),
(67,9,46,'Simple functions','A function is a reusable block of code. Define it with def and call it by name.\n```\ndef greet():\n    print("Hello!")\n\ngreet()\ngreet()\n```\nOutput:\n```\nHello!\nHello!\n```\nTry it: change the values in the playground and run it again.'),
(68,9,47,'Function parameters','Parameters let a function receive values. The values you pass in are called arguments.\n```\ndef greet(name):\n    print("Hello,", name)\n\ngreet("Ana")\ngreet("Ben")\n```\nOutput:\n```\nHello, Ana\nHello, Ben\n```\nTry it: change the values in the playground and run it again.'),
(69,9,48,'Return values','return sends a value back to the caller so you can store it or reuse it.\n```\ndef add(a, b):\n    return a + b\n\nresult = add(3, 4)\nprint(result * 2)\n```\nOutput:\n```\n14\n```\nTry it: change the values in the playground and run it again.'),
(70,9,49,'Default arguments','A default argument is used when the caller does not give a value.\n```\ndef power(base, exp=2):\n    return base ** exp\n\nprint(power(5))\nprint(power(2, 10))\n```\nOutput:\n```\n25\n1024\n```\nTry it: change the values in the playground and run it again.'),
(71,9,50,'Reading error messages','Error messages name the problem and the line. Read the last line first. try and except let you handle an error.\n```\nnumbers = [1, 2, 3]\ntry:\n    print(numbers[5])\nexcept IndexError as err:\n    print("Error:", err)\n```\nOutput:\n```\nError: list index out of range\n```\nTry it: change the values in the playground and run it again.'),
