INSERT INTO `new_lessons`(id,module_id,position,title,body) VALUES
(222,13,1,'Hello console.log','console.log() prints a value in the output. End each statement with a semicolon.\n```\nconsole.log("Hello, world!");\n```\nOutput:\n```\nHello, world!\n```\nTry it: change the values in the playground and run it again.'),
(223,13,2,'Comments','// starts a one-line comment and /* ... */ makes a multi-line comment.\n```\n// ignored\nconsole.log("Comments help people"); // also ignored\n/* this can\n   span lines */\n```\nOutput:\n```\nComments help people\n```\nTry it: change the values in the playground and run it again.'),
(224,13,3,'Variables with let','let creates a variable whose value can change.\n```\nlet score = 10;\nscore = score + 5;\nconsole.log(score);\n```\nOutput:\n```\n15\n```\nTry it: change the values in the playground and run it again.'),
(225,13,4,'Constants with const','const creates a variable that cannot be reassigned. Use it by default.\n```\nconst pi = 3.14;\nconsole.log(pi);\ntry { pi = 3; } catch (e) { console.log("Cannot change a const"); }\n```\nOutput:\n```\n3.14\nCannot change a const\n```\nTry it: change the values in the playground and run it again.'),
(226,13,5,'Why not var','var is the old way. It ignores block scope, which causes surprises, so prefer let and const.\n```\nif (true) {\n  var a = 1;\n  let b = 2;\n}\nconsole.log(a);\nconsole.log(typeof b);\n```\nOutput:\n```\n1\nundefined\n```\nTry it: change the values in the playground and run it again.'),
(227,13,6,'Data types','The main types are number, string, boolean, undefined, null and object. typeof shows the type.\n```\nconsole.log(typeof 42);\nconsole.log(typeof "hi");\nconsole.log(typeof true);\nconsole.log(typeof undefined);\nconsole.log(typeof {});\n```\nOutput:\n```\nnumber\nstring\nboolean\nundefined\nobject\n```\nTry it: change the values in the playground and run it again.'),
(228,13,7,'Numbers','JavaScript has one number type for whole and decimal numbers. Decimals can show tiny rounding errors.\n```\nconsole.log(7 / 2);\nconsole.log(0.1 + 0.2);\nconsole.log(Number.isInteger(5));\n```\nOutput:\n```\n3.5\n0.30000000000000004\ntrue\n```\nTry it: change the values in the playground and run it again.'),
(229,13,8,'Math operators','Use + - * / for math, % for the remainder and ** for powers.\n```\nconsole.log(2 + 3 * 4);\nconsole.log(17 % 5);\nconsole.log(2 ** 5);\n```\nOutput:\n```\n14\n2\n32\n```\nTry it: change the values in the playground and run it again.'),
(230,13,9,'Increment and decrement','++ adds 1, -- subtracts 1 and += adds any amount.\n```\nlet n = 5;\nn++;\nconsole.log(n);\nn += 10;\nconsole.log(n);\nn--;\nconsole.log(n);\n```\nOutput:\n```\n6\n16\n15\n```\nTry it: change the values in the playground and run it again.'),
(231,13,10,'Strings','A string is text in quotes. It has a length and each character has a position starting at 0.\n```\nconst word = "JavaScript";\nconsole.log(word.length);\nconsole.log(word[0]);\nconsole.log(word + "!");\n```\nOutput:\n```\n10\nJ\nJavaScript!\n```\nTry it: change the values in the playground and run it again.'),
(232,13,11,'Template literals','Template literals use backticks and insert values with dollar-brace.\n```\nconst name = "Ana";\nconst score = 95;\nconsole.log(`${name} scored ${score} points`);\n```\nOutput:\n```\nAna scored 95 points\n```\nTry it: change the values in the playground and run it again.'),
(233,13,12,'String methods','Strings have methods like trim, toUpperCase, includes and slice.\n```\nconst s = "  Hello World  ";\nconsole.log(s.trim().toUpperCase());\nconsole.log(s.includes("World"));\nconsole.log(s.trim().slice(0, 5));\n```\nOutput:\n```\nHELLO WORLD\ntrue\nHello\n```\nTry it: change the values in the playground and run it again.'),
(234,13,13,'Booleans','A boolean is true or false. Comparisons produce booleans.\n```\nconst isOpen = true;\nconsole.log(isOpen);\nconsole.log(5 > 3);\nconsole.log(typeof false);\n```\nOutput:\n```\ntrue\ntrue\nboolean\n```\nTry it: change the values in the playground and run it again.'),
(235,13,14,'Comparison operators','Comparison operators are < > <= >= === and !==.\n```\nconsole.log(4 >= 9);\nconsole.log(5 !== 3);\nconsole.log("a" < "b");\n```\nOutput:\n```\nfalse\ntrue\ntrue\n```\nTry it: change the values in the playground and run it again.'),
(236,13,15,'Strict equality','=== compares value and type. == converts types first and can surprise you, so use ===.\n```\nconsole.log(5 === "5");\nconsole.log(5 == "5");\nconsole.log(0 === false);\n```\nOutput:\n```\nfalse\ntrue\nfalse\n```\nTry it: change the values in the playground and run it again.'),
(237,13,16,'Logical operators','&& needs both sides true, || needs one side true and ! flips a value.\n```\nconst age = 20;\nconsole.log(age > 18 && age < 30);\nconsole.log(age < 10 || age > 15);\nconsole.log(!(age > 18));\n```\nOutput:\n```\ntrue\ntrue\nfalse\n```\nTry it: change the values in the playground and run it again.'),
(238,13,17,'if statements','if runs code only when its condition is true.\n```\nconst temp = 32;\nif (temp > 30) {\n  console.log("It is hot");\n}\nconsole.log("Done");\n```\nOutput:\n```\nIt is hot\nDone\n```\nTry it: change the values in the playground and run it again.'),
(239,13,18,'else if','else runs when the if is false and else if tests another condition.\n```\nconst score = 75;\nif (score >= 90) {\n  console.log("A");\n} else if (score >= 70) {\n  console.log("B");\n} else {\n  console.log("Try again");\n}\n```\nOutput:\n```\nB\n```\nTry it: change the values in the playground and run it again.'),
(240,13,19,'Ternary operator','The ternary operator is a short if: condition ? valueIfTrue : valueIfFalse.\n```\nconst age = 17;\nconst label = age >= 18 ? "adult" : "minor";\nconsole.log(label);\n```\nOutput:\n```\nminor\n```\nTry it: change the values in the playground and run it again.'),
(241,13,20,'switch statements','switch picks a branch by matching a value. break stops it from running into the next case.\n```\nconst day = 3;\nswitch (day) {\n  case 1: console.log("Mon"); break;\n  case 3: console.log("Wed"); break;\n  default: console.log("Other");\n}\n```\nOutput:\n```\nWed\n```\nTry it: change the values in the playground and run it again.'),
(242,13,21,'while loops','while repeats as long as its condition is true.\n```\nlet count = 1;\nwhile (count <= 3) {\n  console.log("Round " + count);\n  count++;\n}\n```\nOutput:\n```\nRound 1\nRound 2\nRound 3\n```\nTry it: change the values in the playground and run it again.'),
(243,13,22,'for loops','A for loop has a start, a condition and a step.\n```\nfor (let i = 0; i < 3; i++) {\n  console.log(i);\n}\n```\nOutput:\n```\n0\n1\n2\n```\nTry it: change the values in the playground and run it again.'),
(244,13,23,'do while loops','do while runs the body once first and then checks the condition.\n```\nlet n = 10;\ndo {\n  console.log(n);\n  n++;\n} while (n < 10);\n```\nOutput:\n```\n10\n```\nTry it: change the values in the playground and run it again.'),
(245,13,24,'break and continue','break leaves a loop and continue skips to the next round.\n```\nfor (let n = 1; n <= 7; n++) {\n  if (n === 3) continue;\n  if (n === 6) break;\n  console.log(n);\n}\n```\nOutput:\n```\n1\n2\n4\n5\n```\nTry it: change the values in the playground and run it again.'),
(246,13,25,'Arrays','An array holds many values in order, in square brackets.\n```\nconst colors = ["red", "green", "blue"];\nconsole.log(colors.join(","));\nconsole.log(Array.isArray(colors));\n```\nOutput:\n```\nred,green,blue\ntrue\n```\nTry it: change the values in the playground and run it again.'),
(247,13,26,'Array indexing','Positions start at 0 and at(-1) reads from the end.\n```\nconst colors = ["red", "green", "blue"];\nconsole.log(colors[0]);\nconsole.log(colors[2]);\nconsole.log(colors.at(-1));\n```\nOutput:\n```\nred\nblue\nblue\n```\nTry it: change the values in the playground and run it again.'),
(248,13,27,'Push and pop','push adds to the end and pop removes from the end.\n```\nconst nums = [1, 2];\nnums.push(3);\nconsole.log(nums.join(","));\nconsole.log(nums.pop());\nconsole.log(nums.join(","));\n```\nOutput:\n```\n1,2,3\n3\n1,2\n```\nTry it: change the values in the playground and run it again.'),
(249,13,28,'Shift and unshift','unshift adds to the start and shift removes from the start.\n```\nconst q = ["b", "c"];\nq.unshift("a");\nconsole.log(q.join(""));\nconsole.log(q.shift());\nconsole.log(q.join(""));\n```\nOutput:\n```\nabc\na\nbc\n```\nTry it: change the values in the playground and run it again.'),
(250,13,29,'Array length','length is the number of items. The last position is length minus 1.\n```\nconst items = ["x", "y", "z"];\nconsole.log(items.length);\nconsole.log(items[items.length - 1]);\n```\nOutput:\n```\n3\nz\n```\nTry it: change the values in the playground and run it again.'),
(251,13,30,'Looping arrays','Loop over an array with a for loop and the position.\n```\nconst fruits = ["apple", "mango", "kiwi"];\nfor (let i = 0; i < fruits.length; i++) {\n  console.log(i, fruits[i]);\n}\n```\nOutput:\n```\n0 apple\n1 mango\n2 kiwi\n```\nTry it: change the values in the playground and run it again.'),
(252,13,31,'for of loops','for of gives each item directly, with no position to manage.\n```\nfor (const fruit of ["apple", "mango", "kiwi"]) {\n  console.log(fruit);\n}\n```\nOutput:\n```\napple\nmango\nkiwi\n```\nTry it: change the values in the playground and run it again.'),
(253,13,32,'Objects','An object stores named values, called properties, in braces.\n```\nconst student = { name: "Ana", age: 20 };\nconsole.log(student.name);\nconsole.log(student.age);\n```\nOutput:\n```\nAna\n20\n```\nTry it: change the values in the playground and run it again.'),
(254,13,33,'Object properties','Add, change or delete properties at any time.\n```\nconst car = { brand: "Toyota" };\ncar.year = 2020;\ncar.brand = "Honda";\ndelete car.year;\nconsole.log(car.brand, car.year);\n```\nOutput:\n```\nHonda undefined\n```\nTry it: change the values in the playground and run it again.'),
(255,13,34,'Dot and bracket notation','Use dot notation for known names. Use brackets when the name is in a variable or has spaces.\n```\nconst user = { name: "Ana", "home town": "Quezon City" };\nconst key = "name";\nconsole.log(user.name);\nconsole.log(user[key]);\nconsole.log(user["home town"]);\n```\nOutput:\n```\nAna\nAna\nQuezon City\n```\nTry it: change the values in the playground and run it again.'),
(256,13,35,'Nested objects','Objects can hold other objects and arrays.\n```\nconst school = { name: "ABC", address: { city: "Manila" }, rooms: [101, 102] };\nconsole.log(school.address.city);\nconsole.log(school.rooms[1]);\n```\nOutput:\n```\nManila\n102\n```\nTry it: change the values in the playground and run it again.'),
(257,13,36,'Functions','A function is a reusable block of code. Declare it with function and call it by name.\n```\nfunction greet() {\n  console.log("Hello!");\n}\ngreet();\ngreet();\n```\nOutput:\n```\nHello!\nHello!\n```\nTry it: change the values in the playground and run it again.'),
(258,13,37,'Parameters','Parameters receive values. The values you pass in are called arguments.\n```\nfunction greet(name) {\n  console.log("Hello, " + name);\n}\ngreet("Ana");\ngreet("Ben");\n```\nOutput:\n```\nHello, Ana\nHello, Ben\n```\nTry it: change the values in the playground and run it again.'),
(259,13,38,'Return values','return sends a value back to the caller.\n```\nfunction add(a, b) {\n  return a + b;\n}\nconst result = add(3, 4);\nconsole.log(result * 2);\n```\nOutput:\n```\n14\n```\nTry it: change the values in the playground and run it again.'),
(260,13,39,'Default parameters','A default parameter is used when no argument is given.\n```\nfunction power(base, exp = 2) {\n  return base ** exp;\n}\nconsole.log(power(5));\nconsole.log(power(2, 10));\n```\nOutput:\n```\n25\n1024\n```\nTry it: change the values in the playground and run it again.'),
(261,13,40,'Arrow functions','An arrow function is a shorter way to write a function.\n```\nconst square = n => n * n;\nconst add = (a, b) => a + b;\nconsole.log(square(6));\nconsole.log(add(2, 3));\n```\nOutput:\n```\n36\n5\n```\nTry it: change the values in the playground and run it again.');
INSERT INTO `new_lessons`(id,module_id,position,title,body) VALUES
(262,13,41,'Function expressions','A function expression stores a function in a variable.\n```\nconst shout = function (text) {\n  return text.toUpperCase() + "!";\n};\nconsole.log(shout("hey"));\n```\nOutput:\n```\nHEY!\n```\nTry it: change the values in the playground and run it again.'),
(263,13,42,'Scope','Scope decides where a variable can be used. let and const stay inside their braces.\n```\nconst outer = "everywhere";\nfunction show() {\n  const inner = "only here";\n  console.log(outer, inner);\n}\nshow();\nconsole.log(typeof inner);\n```\nOutput:\n```\neverywhere only here\nundefined\n```\nTry it: change the values in the playground and run it again.'),
(264,13,43,'Type conversion','Convert with Number(), String() and Boolean(). The + operator joins when one side is text.\n```\nconsole.log(Number("42") + 8);\nconsole.log("5" + 3);\nconsole.log("5" * 3);\nconsole.log(String(10) + "!");\nconsole.log(Boolean(""));\n```\nOutput:\n```\n50\n53\n15\n10!\nfalse\n```\nTry it: change the values in the playground and run it again.'),
(265,13,44,'NaN and undefined','undefined means no value was given. NaN means a failed number calculation.\n```\nlet x;\nconsole.log(x);\nconsole.log(Number("abc"));\nconsole.log(isNaN(Number("abc")));\n```\nOutput:\n```\nundefined\nNaN\ntrue\n```\nTry it: change the values in the playground and run it again.'),
(266,13,45,'null vs undefined','null is an empty value you set on purpose. undefined means nothing was ever set.\n```\nlet a = null;\nlet b;\nconsole.log(a, b);\nconsole.log(a == b);\nconsole.log(a === b);\n```\nOutput:\n```\nnull undefined\ntrue\nfalse\n```\nTry it: change the values in the playground and run it again.'),
(267,13,46,'Math object','The Math object has round, floor, ceil, max, min, sqrt and abs.\n```\nconsole.log(Math.round(2.6));\nconsole.log(Math.floor(2.9));\nconsole.log(Math.ceil(2.1));\nconsole.log(Math.max(3, 9, 4));\nconsole.log(Math.sqrt(81));\n```\nOutput:\n```\n3\n2\n3\n9\n9\n```\nTry it: change the values in the playground and run it again.'),
(268,13,47,'Random numbers','Math.random() gives a number from 0 up to but not including 1. Scale it to get a range. The roll changes every run, so we print only a check.\n```\nconst roll = Math.floor(Math.random() * 6) + 1;\nconsole.log(roll >= 1 && roll <= 6);\nconsole.log("You rolled between 1 and 6");\n```\nOutput:\n```\ntrue\nYou rolled between 1 and 6\n```\nTry it: change the values in the playground and run it again.'),
(269,13,48,'Date basics','A Date holds a moment in time. new Date(year, monthIndex, day) counts months from 0 to 11.\n```\nconst d = new Date(2026, 0, 15);\nconsole.log(d.getFullYear());\nconsole.log(d.getMonth());\nconsole.log(d.getDate());\n```\nOutput:\n```\n2026\n0\n15\n```\nTry it: change the values in the playground and run it again.'),
(270,13,49,'Reading error messages','Errors have a name and a message. try and catch let your program handle them.\n```\ntry {\n  console.log(missing);\n} catch (err) {\n  console.log(err.name + ": " + err.message);\n}\n```\nOutput:\n```\nReferenceError: missing is not defined\n```\nTry it: change the values in the playground and run it again.'),
(271,13,50,'Console methods','console.log is the one you use most. warn and error also print in this playground, and JSON.stringify shows an object as text.\n```\nconsole.log("normal");\nconsole.log([1, 2, 3].length);\nconsole.log(JSON.stringify({ a: 1, b: [2, 3] }));\nconsole.log(typeof console.log);\n```\nOutput:\n```\nnormal\n3\n{"a":1,"b":[2,3]}\nfunction\n```\nTry it: change the values in the playground and run it again.'),
