INSERT INTO `new_lessons`(id,module_id,position,title,body) VALUES
(422,17,1,'Hello, cout','cout prints text to the screen. << sends values to it and endl ends the line.\n```\n#include <iostream>\n#include <string>\n#include <vector>\nusing namespace std;\n\nint main() {\n    cout << "Hello, world!" << endl;\n    return 0;\n}\n```\nOutput:\n```\nHello, world!\n```\nTry it: copy this into the playground and change it.'),
(423,17,2,'Variables and types','Every variable has a type: int for whole numbers, double for decimals and string for text.\n```\n#include <iostream>\n#include <string>\n#include <vector>\nusing namespace std;\n\nint main() {\n    int age = 18;\n    double price = 2.5;\n    string name = "Ana";\n    cout << name << " " << age << " " << price << endl;\n    return 0;\n}\n```\nOutput:\n```\nAna 18 2.5\n```\nTry it: copy this into the playground and change it.'),
(424,17,3,'Math operators','Division of two ints drops the decimals. Use a double to keep them. % gives the remainder.\n```\n#include <iostream>\n#include <string>\n#include <vector>\nusing namespace std;\n\nint main() {\n    cout << 2 + 3 * 4 << endl;\n    cout << 17 / 5 << endl;\n    cout << 17 % 5 << endl;\n    cout << 17 / 5.0 << endl;\n    return 0;\n}\n```\nOutput:\n```\n14\n3\n2\n3.4\n```\nTry it: copy this into the playground and change it.'),
(425,17,4,'Strings','A string has a length, positions that start at 0, and can be joined with +.\n```\n#include <iostream>\n#include <string>\n#include <vector>\nusing namespace std;\n\nint main() {\n    string s = "C++ rocks";\n    cout << s.length() << endl;\n    cout << s + "!" << endl;\n    cout << s[0] << endl;\n    return 0;\n}\n```\nOutput:\n```\n9\nC++ rocks!\nC\n```\nTry it: copy this into the playground and change it.'),
(426,17,5,'if and else','if runs code only when its condition is true. else if and else cover the other cases.\n```\n#include <iostream>\n#include <string>\n#include <vector>\nusing namespace std;\n\nint main() {\n    int score = 75;\n    if (score >= 90) {\n        cout << "A" << endl;\n    } else if (score >= 70) {\n        cout << "B" << endl;\n    } else {\n        cout << "Try again" << endl;\n    }\n    return 0;\n}\n```\nOutput:\n```\nB\n```\nTry it: copy this into the playground and change it.'),
(427,17,6,'Comparison and logic','&& needs both sides true, || needs one and ! flips a value. A bool prints as 1 or 0.\n```\n#include <iostream>\n#include <string>\n#include <vector>\nusing namespace std;\n\nint main() {\n    int age = 20;\n    cout << (age > 18 && age < 30) << endl;\n    cout << (age < 10 || age > 15) << endl;\n    cout << !(age > 18) << endl;\n    return 0;\n}\n```\nOutput:\n```\n1\n1\n0\n```\nTry it: copy this into the playground and change it.'),
(428,17,7,'while loops','A while loop repeats as long as its condition is true.\n```\n#include <iostream>\n#include <string>\n#include <vector>\nusing namespace std;\n\nint main() {\n    int i = 1;\n    while (i <= 3) {\n        cout << "Round " << i << endl;\n        i++;\n    }\n    return 0;\n}\n```\nOutput:\n```\nRound 1\nRound 2\nRound 3\n```\nTry it: copy this into the playground and change it.'),
(429,17,8,'for loops','A for loop has a start, a condition and a step.\n```\n#include <iostream>\n#include <string>\n#include <vector>\nusing namespace std;\n\nint main() {\n    for (int i = 0; i < 3; i++) {\n        cout << i << endl;\n    }\n    return 0;\n}\n```\nOutput:\n```\n0\n1\n2\n```\nTry it: copy this into the playground and change it.'),
(430,17,9,'Vectors','A vector is a list that can grow. push_back adds an item and size counts the items.\n```\n#include <iostream>\n#include <string>\n#include <vector>\nusing namespace std;\n\nint main() {\n    vector<int> nums = {4, 9, 2};\n    nums.push_back(7);\n    cout << nums.size() << endl;\n    cout << nums[1] << endl;\n    for (int n : nums) {\n        cout << n << " ";\n    }\n    cout << endl;\n    return 0;\n}\n```\nOutput:\n```\n4\n9\n4 9 2 7\n```\nTry it: copy this into the playground and change it.'),
(431,17,10,'Functions','A function groups code you can call again. It lists the type it returns and its parameters.\n```\n#include <iostream>\nusing namespace std;\n\nint add(int a, int b) {\n    return a + b;\n}\n\nint main() {\n    cout << add(3, 4) << endl;\n    return 0;\n}\n```\nOutput:\n```\n7\n```\nTry it: copy this into the playground and change it.'),
(432,17,11,'References and pointers','A reference is another name for a variable. A pointer holds an address and * reads the value there.\n```\n#include <iostream>\n#include <string>\n#include <vector>\nusing namespace std;\n\nint main() {\n    int x = 5;\n    int& ref = x;\n    ref = 9;\n    cout << x << endl;\n    int* p = &x;\n    cout << *p << endl;\n    return 0;\n}\n```\nOutput:\n```\n9\n9\n```\nTry it: copy this into the playground and change it.'),
(433,17,12,'Classes','A class bundles data and functions. Create an object from it and use the dot to reach its members.\n```\n#include <iostream>\n#include <string>\nusing namespace std;\n\nclass Dog {\npublic:\n    string name;\n    void speak() { cout << name << " says woof" << endl; }\n};\n\nint main() {\n    Dog d;\n    d.name = "Rex";\n    d.speak();\n    return 0;\n}\n```\nOutput:\n```\nRex says woof\n```\nTry it: copy this into the playground and change it.'),
(434,18,1,'Hello, Console.WriteLine','Console.WriteLine prints a line of text. Every statement ends with a semicolon.\n```\nConsole.WriteLine("Hello, world!");\n```\nTry it: copy this into the playground and change it.'),
(435,18,2,'Variables and types','Every variable has a type: int, double, string and more.\n```\nint age = 18;\ndouble price = 2.5;\nstring name = "Ana";\nConsole.WriteLine(name + " " + age + " " + price);\n```\nTry it: copy this into the playground and change it.'),
(436,18,3,'Math operators','Dividing two ints drops the decimals. Use a double to keep them. % gives the remainder.\n```\nConsole.WriteLine(2 + 3 * 4);\nConsole.WriteLine(17 / 5);\nConsole.WriteLine(17 % 5);\nConsole.WriteLine(17 / 5.0);\n```\nTry it: copy this into the playground and change it.'),
(437,18,4,'Strings','Strings have a Length and methods like ToUpper. A string with $ in front can hold values in braces.\n```\nstring s = "C# is fun";\nConsole.WriteLine(s.Length);\nConsole.WriteLine(s.ToUpper());\nConsole.WriteLine($"Length is {s.Length}");\n```\nTry it: copy this into the playground and change it.'),
(438,18,5,'if and else','if runs code only when its condition is true.\n```\nint score = 75;\nif (score >= 90)\n{\n    Console.WriteLine("A");\n}\nelse if (score >= 70)\n{\n    Console.WriteLine("B");\n}\nelse\n{\n    Console.WriteLine("Try again");\n}\n```\nTry it: copy this into the playground and change it.'),
(439,18,6,'Comparison and logic','&& needs both sides true, || needs one and ! flips a value. A bool prints as True or False.\n```\nint age = 20;\nConsole.WriteLine(age > 18 && age < 30);\nConsole.WriteLine(age < 10 || age > 15);\nConsole.WriteLine(!(age > 18));\n```\nTry it: copy this into the playground and change it.'),
(440,18,7,'while loops','A while loop repeats as long as its condition is true.\n```\nint i = 1;\nwhile (i <= 3)\n{\n    Console.WriteLine("Round " + i);\n    i++;\n}\n```\nTry it: copy this into the playground and change it.'),
(441,18,8,'for loops','A for loop has a start, a condition and a step.\n```\nfor (int i = 0; i < 3; i++)\n{\n    Console.WriteLine(i);\n}\n```\nTry it: copy this into the playground and change it.'),
(442,18,9,'Arrays and lists','An array has a fixed size. A List can grow with Add.\n```\nint[] a = { 4, 9, 2 };\nList<int> list = new List<int> { 4, 9, 2 };\nlist.Add(7);\nConsole.WriteLine(a.Length);\nConsole.WriteLine(list.Count);\nforeach (int n in list)\n{\n    Console.Write(n + " ");\n}\nConsole.WriteLine();\n```\nTry it: copy this into the playground and change it.'),
(443,18,10,'Methods','A method groups code you can call again. It lists the type it returns and its parameters.\n```\nint Add(int a, int b)\n{\n    return a + b;\n}\n\nConsole.WriteLine(Add(3, 4));\n```\nTry it: copy this into the playground and change it.'),
(444,18,11,'Classes','A class bundles data and methods. Put the class after your statements and create objects with new.\n```\nvar d = new Dog { Name = "Rex" };\nd.Speak();\n\nclass Dog\n{\n    public string Name;\n    public void Speak() { Console.WriteLine(Name + " says woof"); }\n}\n```\nTry it: copy this into the playground and change it.'),
(445,18,12,'Dictionaries','A Dictionary stores key and value pairs. foreach visits each pair.\n```\nvar ages = new Dictionary<string, int> { { "Ana", 20 }, { "Ben", 25 } };\nforeach (var pair in ages)\n{\n    Console.WriteLine(pair.Key + " is " + pair.Value);\n}\n```\nTry it: copy this into the playground and change it.'),
(446,19,1,'Hello, echo','echo prints text. Every PHP file starts with the opening tag and every statement ends with a semicolon. PHP_EOL adds a new line.\n```\n<?php\necho "Hello, world!" . PHP_EOL;\n```\nTry it: copy this into the playground and change it.'),
(447,19,2,'Variables','PHP variables start with a dollar sign. A dot joins text.\n```\n<?php\n$name = "Ana";\n$age = 18;\necho $name . " is " . $age . PHP_EOL;\n```\nTry it: copy this into the playground and change it.'),
(448,19,3,'Math operators','Use + - * / and % for math. intdiv() gives the whole-number part of a division.\n```\n<?php\necho (2 + 3 * 4) . PHP_EOL;\necho (17 % 5) . PHP_EOL;\necho intdiv(17, 5) . PHP_EOL;\necho (17 / 5) . PHP_EOL;\n```\nTry it: copy this into the playground and change it.'),
(449,19,4,'Strings','PHP has many string functions, and double-quoted strings can hold variables.\n```\n<?php\n$s = "PHP is fun";\necho strlen($s) . PHP_EOL;\necho strtoupper($s) . PHP_EOL;\necho "Hello, $s" . PHP_EOL;\n```\nTry it: copy this into the playground and change it.'),
(450,19,5,'if and else','if runs code only when its condition is true. elseif and else cover the other cases.\n```\n<?php\n$score = 75;\nif ($score >= 90) {\n    echo "A" . PHP_EOL;\n} elseif ($score >= 70) {\n    echo "B" . PHP_EOL;\n} else {\n    echo "Try again" . PHP_EOL;\n}\n```\nTry it: copy this into the playground and change it.'),
(451,19,6,'Comparison','== converts types before comparing and === also checks the type. var_dump shows the type and value.\n```\n<?php\n$age = 20;\nvar_dump($age > 18 && $age < 30);\nvar_dump("5" == 5);\nvar_dump("5" === 5);\n```\nTry it: copy this into the playground and change it.'),
(452,19,7,'while loops','A while loop repeats as long as its condition is true.\n```\n<?php\n$i = 1;\nwhile ($i <= 3) {\n    echo "Round $i" . PHP_EOL;\n    $i++;\n}\n```\nTry it: copy this into the playground and change it.'),
(453,19,8,'for loops','A for loop has a start, a condition and a step.\n```\n<?php\nfor ($i = 0; $i < 3; $i++) {\n    echo $i . PHP_EOL;\n}\n```\nTry it: copy this into the playground and change it.'),
(454,19,9,'Arrays','An array holds many values. Use [] to add one and count() to count them.\n```\n<?php\n$nums = [4, 9, 2];\n$nums[] = 7;\necho count($nums) . PHP_EOL;\necho $nums[1] . PHP_EOL;\nforeach ($nums as $n) {\n    echo $n . " ";\n}\necho PHP_EOL;\n```\nTry it: copy this into the playground and change it.'),
(455,19,10,'Associative arrays','An associative array maps keys to values.\n```\n<?php\n$age = ["Ana" => 20, "Ben" => 25];\n$age["Cy"] = 30;\nforeach ($age as $name => $a) {\n    echo "$name is $a" . PHP_EOL;\n}\n```\nTry it: copy this into the playground and change it.'),
(456,19,11,'Functions','A function groups code you can call again. return sends a value back.\n```\n<?php\nfunction add($a, $b) {\n    return $a + $b;\n}\necho add(3, 4) . PHP_EOL;\n```\nTry it: copy this into the playground and change it.'),
(457,19,12,'Classes','A class bundles data and functions. Create an object with new and reach its members with an arrow.\n```\n<?php\nclass Dog {\n    public $name;\n    function speak() {\n        echo $this->name . " says woof" . PHP_EOL;\n    }\n}\n$d = new Dog();\n$d->name = "Rex";\n$d->speak();\n```\nTry it: copy this into the playground and change it.'),
(458,17,13,'Type conversion','**Type conversion** changes a **value** from one **type** to another. Text must become a number before you can do math with it.\n\nExample 1:\n```\n#include <iostream>\n#include <string>\n#include <vector>\nusing namespace std;\n\nint main() {\n    string t = "42";\n    int n = stoi(t);\n    cout << (n + 8) << endl;\n    return 0;\n}\n```\nOutput:\n```\n50\n```\n\nExample 2:\n```\n#include <iostream>\n#include <string>\n#include <vector>\nusing namespace std;\n\nint main() {\n    int n = 7;\n    string s = to_string(n);\n    cout << (s + " days") << endl;\n    return 0;\n}\n```\nOutput:\n```\n7 days\n```\n\nExample 3:\n```\n#include <iostream>\n#include <string>\n#include <vector>\nusing namespace std;\n\nint main() {\n    string t = "8";\n    int n = stoi(t);\n    cout << (n + 10) << endl;\n    return 0;\n}\n```\nOutput:\n```\n18\n```\n\nPractice: change the numbers or words in Example 1, then guess the new output before you run it.'),
(459,17,14,'Constants','A **constant** is a value that never changes, such as a tax rate. Write it in capital letters so it is easy to spot.\n\nExample 1:\n```\n#include <iostream>\n#include <string>\n#include <vector>\nusing namespace std;\n\nint main() {\n    const int MAX = 5;\n    cout << ("Max is ") << (MAX) << endl;\n    return 0;\n}\n```\nOutput:\n```\nMax is 5\n```\n\nExample 2:\n```\n#include <iostream>\n#include <string>\n#include <vector>\nusing namespace std;\n\nint main() {\n    const double PI = 3.14;\n    int r = 2;\n    cout << (PI * r * r) << endl;\n    return 0;\n}\n```\nOutput:\n```\n12.56\n```\n\nPractice: change the numbers or words in Example 1, then guess the new output before you run it.'),
(460,17,15,'Comments','A **comment** is a note for people. The computer **ignores** it. Use comments to explain what your code does.\n\nExample 1:\n```\n#include <iostream>\n#include <string>\n#include <vector>\nusing namespace std;\n\nint main() {\n    // This line is a comment\n    cout << ("Hello") << endl;\n    // Comments help people read code\n    return 0;\n}\n```\nOutput:\n```\nHello\n```\n\nExample 2:\n```\n#include <iostream>\n#include <string>\n#include <vector>\nusing namespace std;\n\nint main() {\n    // Calculate the total\n    int price = 20;\n    int qty = 3;\n    cout << (price * qty) << endl;\n    return 0;\n}\n```\nOutput:\n```\n60\n```\n\nPractice: change the numbers or words in Example 1, then guess the new output before you run it.'),
(461,17,16,'Naming rules','Give every **variable** a clear **name**. Use letters, digits and underscores, and never start with a digit. Capital letters matter.\n\nExample 1:\n```\n#include <iostream>\n#include <string>\n#include <vector>\nusing namespace std;\n\nint main() {\n    int studentAge = 17;\n    int total_score = 90;\n    cout << (studentAge + total_score) << endl;\n    return 0;\n}\n```\nOutput:\n```\n107\n```\n\nExample 2:\n```\n#include <iostream>\n#include <string>\n#include <vector>\nusing namespace std;\n\nint main() {\n    string firstName = "Ana";\n    cout << ("Hello ") << (firstName) << endl;\n    return 0;\n}\n```\nOutput:\n```\nHello Ana\n```\n\nExample 3:\n```\n#include <iostream>\n#include <string>\n#include <vector>\nusing namespace std;\n\nint main() {\n    int studentAge = 7;\n    int total_score = 5;\n    cout << (studentAge + total_score) << endl;\n    return 0;\n}\n```\nOutput:\n```\n12\n```\n\nPractice: change the numbers or words in Example 1, then guess the new output before you run it.');
INSERT INTO `new_lessons`(id,module_id,position,title,body) VALUES
(462,17,17,'Booleans','A **boolean** is either **true** or **false**. Use it for yes or no answers and for **conditions**.\n\nExample 1:\n```\n#include <iostream>\n#include <string>\n#include <vector>\nusing namespace std;\n\nint main() {\n    bool isOpen = true;\n    if (isOpen) {\n        cout << ("Open") << endl;\n    } else {\n        cout << ("Closed") << endl;\n    }\n    return 0;\n}\n```\nOutput:\n```\nOpen\n```\n\nExample 2:\n```\n#include <iostream>\n#include <string>\n#include <vector>\nusing namespace std;\n\nint main() {\n    int age = 20;\n    bool adult = age >= 18;\n    if (adult) {\n        cout << ("Adult") << endl;\n    }\n    return 0;\n}\n```\nOutput:\n```\nAdult\n```\n\nPractice: change the numbers or words in Example 1, then guess the new output before you run it.'),
(463,17,18,'Increment and decrement','**++** adds 1 to a variable and **--** subtracts 1. They are handy for counting.\n\nExample 1:\n```\n#include <iostream>\n#include <string>\n#include <vector>\nusing namespace std;\n\nint main() {\n    int n = 5;\n    n++;\n    cout << (n) << endl;\n    n--;\n    cout << (n) << endl;\n    return 0;\n}\n```\nOutput:\n```\n6\n5\n```\n\nExample 2:\n```\n#include <iostream>\n#include <string>\n#include <vector>\nusing namespace std;\n\nint main() {\n    int count = 0;\n    for (int i = 0; i < 4; i++) {\n        count++;\n    }\n    cout << (count) << endl;\n    return 0;\n}\n```\nOutput:\n```\n4\n```\n\nPractice: change the numbers or words in Example 1, then guess the new output before you run it.'),
(464,17,19,'Compound assignment','**Compound assignment** changes a variable using its own value: **+=**, **-=**, ***=** and **/=**.\n\nExample 1:\n```\n#include <iostream>\n#include <string>\n#include <vector>\nusing namespace std;\n\nint main() {\n    int score = 10;\n    score += 5;\n    cout << (score) << endl;\n    score *= 2;\n    cout << (score) << endl;\n    score -= 3;\n    cout << (score) << endl;\n    return 0;\n}\n```\nOutput:\n```\n15\n30\n27\n```\n\nExample 2:\n```\n#include <iostream>\n#include <string>\n#include <vector>\nusing namespace std;\n\nint main() {\n    int x = 20;\n    x /= 4;\n    cout << (x) << endl;\n    return 0;\n}\n```\nOutput:\n```\n5\n```\n\nExample 3:\n```\n#include <iostream>\n#include <string>\n#include <vector>\nusing namespace std;\n\nint main() {\n    int score = 10;\n    score += 8;\n    cout << (score) << endl;\n    score *= 2;\n    cout << (score) << endl;\n    score -= 3;\n    cout << (score) << endl;\n    return 0;\n}\n```\nOutput:\n```\n18\n36\n33\n```\n\nPractice: change the numbers or words in Example 1, then guess the new output before you run it.'),
(465,17,20,'Operator precedence','**Precedence** decides which **operator** runs first. Multiplication and division come before addition and subtraction. Use **brackets** to choose the order yourself.\n\nExample 1:\n```\n#include <iostream>\n#include <string>\n#include <vector>\nusing namespace std;\n\nint main() {\n    cout << (2 + 3 * 4) << endl;\n    cout << ((2 + 3) * 4) << endl;\n    return 0;\n}\n```\nOutput:\n```\n14\n20\n```\n\nExample 2:\n```\n#include <iostream>\n#include <string>\n#include <vector>\nusing namespace std;\n\nint main() {\n    cout << (10 - 4 - 3) << endl;\n    cout << (10 - (4 - 3)) << endl;\n    return 0;\n}\n```\nOutput:\n```\n3\n9\n```\n\nExample 3:\n```\n#include <iostream>\n#include <string>\n#include <vector>\nusing namespace std;\n\nint main() {\n    cout << (2 + 12 * 4) << endl;\n    cout << ((2 + 12) * 4) << endl;\n    return 0;\n}\n```\nOutput:\n```\n50\n56\n```\n\nPractice: change the numbers or words in Example 1, then guess the new output before you run it.'),
(466,17,21,'Nested if','A **nested if** is an if inside another if. The inner check only happens when the outer one is true.\n\nExample 1:\n```\n#include <iostream>\n#include <string>\n#include <vector>\nusing namespace std;\n\nint main() {\n    int age = 20;\n    bool hasId = true;\n    if (age >= 18) {\n        if (hasId) {\n            cout << ("Welcome") << endl;\n        } else {\n            cout << ("Show your ID") << endl;\n        }\n    } else {\n        cout << ("Too young") << endl;\n    }\n    return 0;\n}\n```\nOutput:\n```\nWelcome\n```\n\nExample 2:\n```\n#include <iostream>\n#include <string>\n#include <vector>\nusing namespace std;\n\nint main() {\n    int score = 85;\n    if (score >= 50) {\n        if (score >= 80) {\n            cout << ("Great") << endl;\n        } else {\n            cout << ("Pass") << endl;\n        }\n    }\n    return 0;\n}\n```\nOutput:\n```\nGreat\n```\n\nPractice: change the numbers or words in Example 1, then guess the new output before you run it.'),
(467,17,22,'switch statements','A **switch** picks one **case** by matching a value. **break** stops it from running into the next case, and **default** handles everything else.\n\nExample 1:\n```\n#include <iostream>\n#include <string>\n#include <vector>\nusing namespace std;\n\nint main() {\n    int day = 3;\n    switch (day) {\n        case 1:\n            cout << ("Monday") << endl;\n            break;\n        case 3:\n            cout << ("Wednesday") << endl;\n            break;\n        default:\n            cout << ("Another day") << endl;\n    }\n    return 0;\n}\n```\nOutput:\n```\nWednesday\n```\n\nExample 2:\n```\n#include <iostream>\n#include <string>\n#include <vector>\nusing namespace std;\n\nint main() {\n    int n = 2;\n    switch (n) {\n        case 1:\n        case 2:\n            cout << ("Small") << endl;\n            break;\n        default:\n            cout << ("Big") << endl;\n    }\n    return 0;\n}\n```\nOutput:\n```\nSmall\n```\n\nPractice: change the numbers or words in Example 1, then guess the new output before you run it.'),
(468,17,23,'Ternary operator','The **ternary operator** is a short if: **condition ? valueIfTrue : valueIfFalse**.\n\nExample 1:\n```\n#include <iostream>\n#include <string>\n#include <vector>\nusing namespace std;\n\nint main() {\n    int age = 17;\n    string label = (age >= 18) ? "adult" : "minor";\n    cout << (label) << endl;\n    return 0;\n}\n```\nOutput:\n```\nminor\n```\n\nExample 2:\n```\n#include <iostream>\n#include <string>\n#include <vector>\nusing namespace std;\n\nint main() {\n    int a = 8;\n    int b = 5;\n    int big = (a > b) ? a : b;\n    cout << (big) << endl;\n    return 0;\n}\n```\nOutput:\n```\n8\n```\n\nPractice: change the numbers or words in Example 1, then guess the new output before you run it.'),
(469,17,24,'do while loops','A **do while** loop runs its body **first** and checks the condition **after**, so it always runs at least once.\n\nExample 1:\n```\n#include <iostream>\n#include <string>\n#include <vector>\nusing namespace std;\n\nint main() {\n    int n = 1;\n    do {\n        cout << (n) << endl;\n        n++;\n    } while (n <= 3);\n    return 0;\n}\n```\nOutput:\n```\n1\n2\n3\n```\n\nExample 2:\n```\n#include <iostream>\n#include <string>\n#include <vector>\nusing namespace std;\n\nint main() {\n    int n = 10;\n    do {\n        cout << ("Runs once") << endl;\n        n++;\n    } while (n < 5);\n    return 0;\n}\n```\nOutput:\n```\nRuns once\n```\n\nExample 3:\n```\n#include <iostream>\n#include <string>\n#include <vector>\nusing namespace std;\n\nint main() {\n    int n = 1;\n    do {\n        cout << (n) << endl;\n        n++;\n    } while (n <= 5);\n    return 0;\n}\n```\nOutput:\n```\n1\n2\n3\n4\n5\n```\n\nPractice: change the numbers or words in Example 1, then guess the new output before you run it.'),
(470,17,25,'break and continue','**break** leaves a loop right away. **continue** skips the rest of this round and goes to the next one.\n\nExample 1:\n```\n#include <iostream>\n#include <string>\n#include <vector>\nusing namespace std;\n\nint main() {\n    for (int i = 1; i <= 6; i++) {\n        if (i == 3) {\n            continue;\n        }\n        if (i == 5) {\n            break;\n        }\n        cout << (i) << endl;\n    }\n    return 0;\n}\n```\nOutput:\n```\n1\n2\n4\n```\n\nExample 2:\n```\n#include <iostream>\n#include <string>\n#include <vector>\nusing namespace std;\n\nint main() {\n    int i = 0;\n    while (i < 10) {\n        i += 3;\n        if (i > 7) {\n            break;\n        }\n        cout << (i) << endl;\n    }\n    return 0;\n}\n```\nOutput:\n```\n3\n6\n```\n\nExample 3:\n```\n#include <iostream>\n#include <string>\n#include <vector>\nusing namespace std;\n\nint main() {\n    for (int i = 1; i <= 5; i++) {\n        if (i == 10) {\n            continue;\n        }\n        if (i == 9) {\n            break;\n        }\n        cout << (i) << endl;\n    }\n    return 0;\n}\n```\nOutput:\n```\n1\n2\n3\n4\n5\n```\n\nPractice: change the numbers or words in Example 1, then guess the new output before you run it.'),
(471,17,26,'Nested loops','A **nested loop** is a loop inside a loop. The inner loop runs completely for every round of the outer loop.\n\nExample 1:\n```\n#include <iostream>\n#include <string>\n#include <vector>\nusing namespace std;\n\nint main() {\n    for (int r = 1; r <= 3; r++) {\n        for (int c = 1; c <= 3; c++) {\n            cout << (r * c) << endl;\n        }\n    }\n    return 0;\n}\n```\nOutput:\n```\n1\n2\n3\n2\n4\n6\n3\n6\n9\n```\n\nExample 2:\n```\n#include <iostream>\n#include <string>\n#include <vector>\nusing namespace std;\n\nint main() {\n    for (int i = 1; i <= 4; i++) {\n        string line = "";\n        for (int j = 0; j < i; j++) {\n            line = line + "*";\n        }\n        cout << (line) << endl;\n    }\n    return 0;\n}\n```\nOutput:\n```\n*\n**\n***\n****\n```\n\nExample 3:\n```\n#include <iostream>\n#include <string>\n#include <vector>\nusing namespace std;\n\nint main() {\n    for (int r = 1; r <= 5; r++) {\n        for (int c = 1; c <= 5; c++) {\n            cout << (r * c) << endl;\n        }\n    }\n    return 0;\n}\n```\nOutput:\n```\n1\n2\n3\n4\n5\n2\n4\n6\n8\n10\n3\n6\n9\n12\n15\n4\n8\n12\n16\n20\n5\n10\n15\n20\n25\n```\n\nPractice: change the numbers or words in Example 1, then guess the new output before you run it.'),
(472,17,27,'Counting with loops','Use a **counter** variable that starts at 0 and goes up by 1 each time something matches.\n\nExample 1:\n```\n#include <iostream>\n#include <string>\n#include <vector>\nusing namespace std;\n\nint main() {\n    int count = 0;\n    for (int i = 1; i <= 20; i++) {\n        if (i % 3 == 0) {\n            count++;\n        }\n    }\n    cout << (count) << endl;\n    return 0;\n}\n```\nOutput:\n```\n6\n```\n\nExample 2:\n```\n#include <iostream>\n#include <string>\n#include <vector>\nusing namespace std;\n\nint main() {\n    string word = "banana";\n    int a = 0;\n    for (int i = 0; i < word.length(); i++) {\n        if (word[i] == \'a\') {\n            a++;\n        }\n    }\n    cout << (a) << endl;\n    return 0;\n}\n```\nOutput:\n```\n3\n```\n\nExample 3:\n```\n#include <iostream>\n#include <string>\n#include <vector>\nusing namespace std;\n\nint main() {\n    int count = 0;\n    for (int i = 1; i <= 3; i++) {\n        if (i % 6 == 0) {\n            count++;\n        }\n    }\n    cout << (count) << endl;\n    return 0;\n}\n```\nOutput:\n```\n0\n```\n\nPractice: change the numbers or words in Example 1, then guess the new output before you run it.'),
(473,17,28,'Accumulator pattern','An **accumulator** is a variable that starts at 0 and **adds** to itself each round to build a total.\n\nExample 1:\n```\n#include <iostream>\n#include <string>\n#include <vector>\nusing namespace std;\n\nint main() {\n    int total = 0;\n    for (int i = 1; i <= 5; i++) {\n        total += i;\n    }\n    cout << (total) << endl;\n    return 0;\n}\n```\nOutput:\n```\n15\n```\n\nExample 2:\n```\n#include <iostream>\n#include <string>\n#include <vector>\nusing namespace std;\n\nint main() {\n    vector<int> prices = {5, 10, 20};\n    int sum = 0;\n    for (int p : prices) {\n        sum += p;\n    }\n    cout << ("Total: ") << (sum) << endl;\n    return 0;\n}\n```\nOutput:\n```\nTotal: 35\n```\n\nExample 3:\n```\n#include <iostream>\n#include <string>\n#include <vector>\nusing namespace std;\n\nint main() {\n    int total = 0;\n    for (int i = 1; i <= 4; i++) {\n        total += i;\n    }\n    cout << (total) << endl;\n    return 0;\n}\n```\nOutput:\n```\n10\n```\n\nPractice: change the numbers or words in Example 1, then guess the new output before you run it.'),
(474,17,29,'Arrays basics','An **array** (or **list**) keeps many values under one name. Each value has a **position** called an **index**, and the first index is **0**.\n\nExample 1:\n```\n#include <iostream>\n#include <string>\n#include <vector>\nusing namespace std;\n\nint main() {\n    vector<int> v = {4, 9, 2};\n    cout << (v.at(0)) << endl;\n    cout << (v.at(2)) << endl;\n    cout << (v.size()) << endl;\n    return 0;\n}\n```\nOutput:\n```\n4\n2\n3\n```\n\nExample 2:\n```\n#include <iostream>\n#include <string>\n#include <vector>\nusing namespace std;\n\nint main() {\n    vector<int> scores = {70, 85, 90};\n    for (int s : scores) {\n        cout << (s) << endl;\n    }\n    return 0;\n}\n```\nOutput:\n```\n70\n85\n90\n```\n\nExample 3:\n```\n#include <iostream>\n#include <string>\n#include <vector>\nusing namespace std;\n\nint main() {\n    vector<int> v = {5, 11, 2};\n    cout << (v.at(0)) << endl;\n    cout << (v.at(2)) << endl;\n    cout << (v.size()) << endl;\n    return 0;\n}\n```\nOutput:\n```\n5\n2\n3\n```\n\nPractice: change the numbers or words in Example 1, then guess the new output before you run it.'),
(475,17,30,'Looping arrays','Use a **for** loop with the **index** to visit each item, or a loop that gives you each item directly.\n\nExample 1:\n```\n#include <iostream>\n#include <string>\n#include <vector>\nusing namespace std;\n\nint main() {\n    vector<int> v = {3, 6, 9};\n    for (int i = 0; i < v.size(); i++) {\n        cout << (i) << (": ") << (v.at(i)) << endl;\n    }\n    return 0;\n}\n```\nOutput:\n```\n0: 3\n1: 6\n2: 9\n```\n\nExample 2:\n```\n#include <iostream>\n#include <string>\n#include <vector>\nusing namespace std;\n\nint main() {\n    vector<int> v = {2, 4, 6};\n    int sum = 0;\n    for (int x : v) {\n        sum += x;\n    }\n    cout << (sum) << endl;\n    return 0;\n}\n```\nOutput:\n```\n12\n```\n\nExample 3:\n```\n#include <iostream>\n#include <string>\n#include <vector>\nusing namespace std;\n\nint main() {\n    vector<int> v = {12, 4, 9};\n    for (int i = 0; i < v.size(); i++) {\n        cout << (i) << (": ") << (v.at(i)) << endl;\n    }\n    return 0;\n}\n```\nOutput:\n```\n0: 12\n1: 4\n2: 9\n```\n\nPractice: change the numbers or words in Example 1, then guess the new output before you run it.'),
(476,17,31,'Array length','The **length** tells you how many items are in an array. The **last** index is always the length **minus 1**.\n\nExample 1:\n```\n#include <iostream>\n#include <string>\n#include <vector>\nusing namespace std;\n\nint main() {\n    vector<int> v = {5, 6, 7, 8};\n    cout << (v.size()) << endl;\n    cout << (v.at(v.size() - 1)) << endl;\n    return 0;\n}\n```\nOutput:\n```\n4\n8\n```\n\nExample 2:\n```\n#include <iostream>\n#include <string>\n#include <vector>\nusing namespace std;\n\nint main() {\n    string s = "hello";\n    cout << (s.length()) << endl;\n    cout << (s[s.length() - 1]) << endl;\n    return 0;\n}\n```\nOutput:\n```\n5\no\n```\n\nPractice: change the numbers or words in Example 1, then guess the new output before you run it.'),
(477,17,32,'Searching an array','To **search**, check every item and remember if you found what you want, or remember its **position**.\n\nExample 1:\n```\n#include <iostream>\n#include <string>\n#include <vector>\nusing namespace std;\n\nint main() {\n    vector<int> v = {7, 3, 9, 4};\n    int found = 0;\n    for (int x : v) {\n        if (x == 9) {\n            found = 1;\n        }\n    }\n    if (found == 1) {\n        cout << ("Found it") << endl;\n    } else {\n        cout << ("Not found") << endl;\n    }\n    return 0;\n}\n```\nOutput:\n```\nFound it\n```\n\nExample 2:\n```\n#include <iostream>\n#include <string>\n#include <vector>\nusing namespace std;\n\nint main() {\n    vector<int> v = {7, 3, 9, 4};\n    int pos = -1;\n    for (int i = 0; i < v.size(); i++) {\n        if (v[i] == 3) {\n            pos = i;\n        }\n    }\n    cout << (pos) << endl;\n    return 0;\n}\n```\nOutput:\n```\n1\n```\n\nPractice: change the numbers or words in Example 1, then guess the new output before you run it.'),
(478,17,33,'Finding min and max','Start with the **first** item as the biggest (or smallest) and **replace** it whenever you see a better one.\n\nExample 1:\n```\n#include <iostream>\n#include <string>\n#include <vector>\nusing namespace std;\n\nint main() {\n    vector<int> v = {8, 2, 9, 4};\n    int big = v[0];\n    int small = v[0];\n    for (int x : v) {\n        if (x > big) {\n            big = x;\n        }\n        if (x < small) {\n            small = x;\n        }\n    }\n    cout << ("Biggest: ") << (big) << endl;\n    cout << ("Smallest: ") << (small) << endl;\n    return 0;\n}\n```\nOutput:\n```\nBiggest: 9\nSmallest: 2\n```\n\nExample 2:\n```\n#include <iostream>\n#include <string>\n#include <vector>\nusing namespace std;\n\nint main() {\n    vector<int> temps = {30, 28, 33};\n    int hottest = temps[0];\n    for (int t : temps) {\n        if (t > hottest) {\n            hottest = t;\n        }\n    }\n    cout << (hottest) << endl;\n    return 0;\n}\n```\nOutput:\n```\n33\n```\n\nPractice: change the numbers or words in Example 1, then guess the new output before you run it.'),
(479,17,34,'String methods','A **string** is text. It has a **length**, and **methods** (built-in tools) such as taking a piece of it.\n\nExample 1:\n```\n#include <iostream>\n#include <string>\n#include <vector>\nusing namespace std;\n\nint main() {\n    string s = "Hello World";\n    cout << (s.length()) << endl;\n    cout << (s.substr(0, 5)) << endl;\n    return 0;\n}\n```\nOutput:\n```\n11\nHello\n```\n\nExample 2:\n```\n#include <iostream>\n#include <string>\n#include <vector>\nusing namespace std;\n\nint main() {\n    string a = "code";\n    string b = "smart";\n    string c = a + b;\n    cout << (c) << endl;\n    cout << (c.length()) << endl;\n    return 0;\n}\n```\nOutput:\n```\ncodesmart\n9\n```\n\nExample 3:\n```\n#include <iostream>\n#include <string>\n#include <vector>\nusing namespace std;\n\nint main() {\n    string s = "Hello World";\n    cout << (s.length()) << endl;\n    cout << (s.substr(0, 7)) << endl;\n    return 0;\n}\n```\nOutput:\n```\n11\nHello W\n```\n\nPractice: change the numbers or words in Example 1, then guess the new output before you run it.'),
(480,17,35,'Substrings','A **substring** is a piece of a string. You give the **start** position and how many characters to take.\n\nExample 1:\n```\n#include <iostream>\n#include <string>\n#include <vector>\nusing namespace std;\n\nint main() {\n    string s = "programming";\n    cout << (s.substr(0, 3)) << endl;\n    return 0;\n}\n```\nOutput:\n```\npro\n```\n\nExample 2:\n```\n#include <iostream>\n#include <string>\n#include <vector>\nusing namespace std;\n\nint main() {\n    string s = "programming";\n    cout << (s.substr(3, 4)) << endl;\n    return 0;\n}\n```\nOutput:\n```\ngram\n```\n\nExample 3:\n```\n#include <iostream>\n#include <string>\n#include <vector>\nusing namespace std;\n\nint main() {\n    string s = "programming";\n    cout << (s.substr(0, 8)) << endl;\n    return 0;\n}\n```\nOutput:\n```\nprogramm\n```\n\nPractice: change the numbers or words in Example 1, then guess the new output before you run it.'),
(481,17,36,'Searching text','You can **search** inside a string to see if a word is there and **where** it starts.\n\nExample 1:\n```\n#include <iostream>\n#include <string>\n#include <vector>\nusing namespace std;\n\nint main() {\n    string s = "the cat sat";\n    if (s.find("cat") != string::npos) {\n        cout << ("Found cat") << endl;\n    } else {\n        cout << ("No cat") << endl;\n    }\n    return 0;\n}\n```\nOutput:\n```\nFound cat\n```\n\nExample 2:\n```\n#include <iostream>\n#include <string>\n#include <vector>\nusing namespace std;\n\nint main() {\n    string s = "the cat sat";\n    cout << (s.find("sat")) << endl;\n    return 0;\n}\n```\nOutput:\n```\n8\n```\n\nPractice: change the numbers or words in Example 1, then guess the new output before you run it.'),
(482,17,37,'Formatting output','Join text and values in one line to make clear **output**. An empty print makes a **blank line**.\n\nExample 1:\n```\n#include <iostream>\n#include <string>\n#include <vector>\nusing namespace std;\n\nint main() {\n    string name = "Ana";\n    int score = 95;\n    cout << (name) << (" scored ") << (score) << (" points") << endl;\n    return 0;\n}\n```\nOutput:\n```\nAna scored 95 points\n```\n\nExample 2:\n```\n#include <iostream>\n#include <string>\n#include <vector>\nusing namespace std;\n\nint main() {\n    cout << ("Line 1") << endl;\n    cout << ("") << endl;\n    cout << ("Line 3") << endl;\n    return 0;\n}\n```\nOutput:\n```\nLine 1\n\nLine 3\n```\n\nExample 3:\n```\n#include <iostream>\n#include <string>\n#include <vector>\nusing namespace std;\n\nint main() {\n    string name = "Ana";\n    int score = 3;\n    cout << (name) << (" scored ") << (score) << (" points") << endl;\n    return 0;\n}\n```\nOutput:\n```\nAna scored 3 points\n```\n\nPractice: change the numbers or words in Example 1, then guess the new output before you run it.'),
(483,17,38,'Function parameters','**Parameters** are the inputs of a **function**. The values you pass in when you call it are called **arguments**.\n\nExample 1:\n```\n#include <iostream>\n#include <string>\n#include <vector>\nusing namespace std;\n\nint add(int a, int b) {\n    return a + b;\n}\n\nint main() {\n    cout << (add(3, 4)) << endl;\n    cout << (add(10, 20)) << endl;\n    return 0;\n}\n```\nOutput:\n```\n7\n30\n```\n\nExample 2:\n```\n#include <iostream>\n#include <string>\n#include <vector>\nusing namespace std;\n\nint area(int w, int h) {\n    return w * h;\n}\n\nint main() {\n    cout << ("Area: ") << (area(4, 5)) << endl;\n    return 0;\n}\n```\nOutput:\n```\nArea: 20\n```\n\nExample 3:\n```\n#include <iostream>\n#include <string>\n#include <vector>\nusing namespace std;\n\nint add(int a, int b) {\n    return a + b;\n}\n\nint main() {\n    cout << (add(6, 3)) << endl;\n    cout << (add(9, 11)) << endl;\n    return 0;\n}\n```\nOutput:\n```\n9\n20\n```\n\nPractice: change the numbers or words in Example 1, then guess the new output before you run it.'),
(484,17,39,'Return values','**return** sends a **value** back to the place where the function was called. You can store it or use it right away.\n\nExample 1:\n```\n#include <iostream>\n#include <string>\n#include <vector>\nusing namespace std;\n\nint square(int n) {\n    return n * n;\n}\n\nint main() {\n    int r = square(6);\n    cout << (r) << endl;\n    cout << (square(3) + 1) << endl;\n    return 0;\n}\n```\nOutput:\n```\n36\n10\n```\n\nExample 2:\n```\n#include <iostream>\n#include <string>\n#include <vector>\nusing namespace std;\n\nint bigger(int a, int b) {\n    if (a > b) {\n        return a;\n    }\n    return b;\n}\n\nint main() {\n    cout << (bigger(7, 12)) << endl;\n    return 0;\n}\n```\nOutput:\n```\n12\n```\n\nExample 3:\n```\n#include <iostream>\n#include <string>\n#include <vector>\nusing namespace std;\n\nint square(int n) {\n    return n * n;\n}\n\nint main() {\n    int r = square(10);\n    cout << (r) << endl;\n    cout << (square(9) + 1) << endl;\n    return 0;\n}\n```\nOutput:\n```\n100\n82\n```\n\nPractice: change the numbers or words in Example 1, then guess the new output before you run it.'),
(485,17,40,'Default parameters','A **default parameter** has a value that is used when the caller does not give one.\n\nExample 1:\n```\n#include <iostream>\n#include <string>\n#include <vector>\nusing namespace std;\n\nint power(int base, int times = 2) {\n    int r = 1;\n    for (int i = 0; i < times; i++) {\n        r = r * base;\n    }\n    return r;\n}\n\nint main() {\n    cout << (power(5)) << endl;\n    cout << (power(2, 5)) << endl;\n    return 0;\n}\n```\nOutput:\n```\n25\n32\n```\n\nExample 2:\n```\n#include <iostream>\n#include <string>\n#include <vector>\nusing namespace std;\n\nstring greet(string name = "friend") {\n    return "Hello " + name;\n}\n\nint main() {\n    cout << (greet()) << endl;\n    cout << (greet("Ana")) << endl;\n    return 0;\n}\n```\nOutput:\n```\nHello friend\nHello Ana\n```\n\nPractice: change the numbers or words in Example 1, then guess the new output before you run it.'),
(486,17,41,'Function overview','A **function** is a named block of code you can **call** again and again. It keeps your program short and tidy.\n\nExample 1:\n```\n#include <iostream>\n#include <string>\n#include <vector>\nusing namespace std;\n\nvoid sayHi() {\n    cout << ("Hi!") << endl;\n}\n\nint main() {\n    sayHi();\n    sayHi();\n    return 0;\n}\n```\nOutput:\n```\nHi!\nHi!\n```\n\nExample 2:\n```\n#include <iostream>\n#include <string>\n#include <vector>\nusing namespace std;\n\nvoid line() {\n    cout << ("----------") << endl;\n}\n\nint main() {\n    line();\n    cout << ("Menu") << endl;\n    line();\n    return 0;\n}\n```\nOutput:\n```\n----------\nMenu\n----------\n```\n\nPractice: change the numbers or words in Example 1, then guess the new output before you run it.'),
(487,17,42,'Variable scope','**Scope** is where a variable can be used. A variable made inside a function or loop only exists **there**.\n\nExample 1:\n```\n#include <iostream>\n#include <string>\n#include <vector>\nusing namespace std;\n\nvoid show() {\n    int inner = 5;\n    cout << (inner) << endl;\n}\n\nint main() {\n    int outer = 1;\n    show();\n    cout << (outer) << endl;\n    return 0;\n}\n```\nOutput:\n```\n5\n1\n```\n\nExample 2:\n```\n#include <iostream>\n#include <string>\n#include <vector>\nusing namespace std;\n\nint main() {\n    for (int i = 0; i < 2; i++) {\n        int temp = i * 10;\n        cout << (temp) << endl;\n    }\n    cout << ("Done") << endl;\n    return 0;\n}\n```\nOutput:\n```\n0\n10\nDone\n```\n\nExample 3:\n```\n#include <iostream>\n#include <string>\n#include <vector>\nusing namespace std;\n\nvoid show() {\n    int inner = 3;\n    cout << (inner) << endl;\n}\n\nint main() {\n    int outer = 1;\n    show();\n    cout << (outer) << endl;\n    return 0;\n}\n```\nOutput:\n```\n3\n1\n```\n\nPractice: change the numbers or words in Example 1, then guess the new output before you run it.'),
(488,17,43,'Recursion intro','**Recursion** means a function **calls itself**. It needs a **base case** that stops it.\n\nExample 1:\n```\n#include <iostream>\n#include <string>\n#include <vector>\nusing namespace std;\n\nint countdownSum(int n) {\n    if (n == 0) {\n        return 0;\n    }\n    return n + countdownSum(n - 1);\n}\n\nint main() {\n    cout << (countdownSum(4)) << endl;\n    return 0;\n}\n```\nOutput:\n```\n10\n```\n\nExample 2:\n```\n#include <iostream>\n#include <string>\n#include <vector>\nusing namespace std;\n\nint fact(int n) {\n    if (n <= 1) {\n        return 1;\n    }\n    return n * fact(n - 1);\n}\n\nint main() {\n    cout << (fact(5)) << endl;\n    return 0;\n}\n```\nOutput:\n```\n120\n```\n\nExample 3:\n```\n#include <iostream>\n#include <string>\n#include <vector>\nusing namespace std;\n\nint countdownSum(int n) {\n    if (n == 0) {\n        return 0;\n    }\n    return n + countdownSum(n - 1);\n}\n\nint main() {\n    cout << (countdownSum(6)) << endl;\n    return 0;\n}\n```\nOutput:\n```\n21\n```\n\nPractice: change the numbers or words in Example 1, then guess the new output before you run it.'),
(489,17,44,'Simple calculator','A **calculator** uses the math **operators** on two numbers. Whole-number division drops the decimals.\n\nExample 1:\n```\n#include <iostream>\n#include <string>\n#include <vector>\nusing namespace std;\n\nint main() {\n    int a = 12;\n    int b = 4;\n    cout << (a + b) << endl;\n    cout << (a - b) << endl;\n    cout << (a * b) << endl;\n    cout << ((a / b)) << endl;\n    return 0;\n}\n```\nOutput:\n```\n16\n8\n48\n3\n```\n\nExample 2:\n```\n#include <iostream>\n#include <string>\n#include <vector>\nusing namespace std;\n\nint main() {\n    int x = 9;\n    int y = 3;\n    int op = 3;\n    switch (op) {\n        case 1:\n            cout << (x + y) << endl;\n            break;\n        case 3:\n            cout << (x * y) << endl;\n            break;\n        default:\n            cout << ("Unknown") << endl;\n    }\n    return 0;\n}\n```\nOutput:\n```\n27\n```\n\nExample 3:\n```\n#include <iostream>\n#include <string>\n#include <vector>\nusing namespace std;\n\nint main() {\n    int a = 4;\n    int b = 9;\n    cout << (a + b) << endl;\n    cout << (a - b) << endl;\n    cout << (a * b) << endl;\n    cout << ((a / b)) << endl;\n    return 0;\n}\n```\nOutput:\n```\n13\n-5\n36\n0\n```\n\nPractice: change the numbers or words in Example 1, then guess the new output before you run it.'),
(490,17,45,'Number guessing logic','A guessing game **compares** the guess with a secret number and tells the player **too low**, **too high** or **correct**.\n\nExample 1:\n```\n#include <iostream>\n#include <string>\n#include <vector>\nusing namespace std;\n\nint main() {\n    int secret = 7;\n    int guess = 4;\n    if (guess == secret) {\n        cout << ("Correct") << endl;\n    } else if (guess < secret) {\n        cout << ("Too low") << endl;\n    } else {\n        cout << ("Too high") << endl;\n    }\n    return 0;\n}\n```\nOutput:\n```\nToo low\n```\n\nExample 2:\n```\n#include <iostream>\n#include <string>\n#include <vector>\nusing namespace std;\n\nint main() {\n    vector<int> guesses = {3, 9, 7};\n    int secret = 7;\n    for (int g : guesses) {\n        if (g == secret) {\n            cout << ("Got it: ") << (g) << endl;\n        } else {\n            cout << ("Try again") << endl;\n        }\n    }\n    return 0;\n}\n```\nOutput:\n```\nTry again\nTry again\nGot it: 7\n```\n\nExample 3:\n```\n#include <iostream>\n#include <string>\n#include <vector>\nusing namespace std;\n\nint main() {\n    int secret = 3;\n    int guess = 12;\n    if (guess == secret) {\n        cout << ("Correct") << endl;\n    } else if (guess < secret) {\n        cout << ("Too low") << endl;\n    } else {\n        cout << ("Too high") << endl;\n    }\n    return 0;\n}\n```\nOutput:\n```\nToo high\n```\n\nPractice: change the numbers or words in Example 1, then guess the new output before you run it.'),
(491,17,46,'Temperature converter','To change **Celsius** to **Fahrenheit**, multiply by 9, divide by 5 and add 32.\n\nExample 1:\n```\n#include <iostream>\n#include <string>\n#include <vector>\nusing namespace std;\n\nint main() {\n    int c = 20;\n    int f = c * 9 / 5 + 32;\n    cout << (f) << endl;\n    return 0;\n}\n```\nOutput:\n```\n68\n```\n\nExample 2:\n```\n#include <iostream>\n#include <string>\n#include <vector>\nusing namespace std;\n\nint main() {\n    for (int c = 0; c <= 40; c += 20) {\n        cout << (c) << (" C = ") << (c * 9 / 5 + 32) << (" F") << endl;\n    }\n    return 0;\n}\n```\nOutput:\n```\n0 C = 32 F\n20 C = 68 F\n40 C = 104 F\n```\n\nPractice: change the numbers or words in Example 1, then guess the new output before you run it.'),
(492,17,47,'Grade calculator','A **grade calculator** uses **if / else if** to turn a score into a letter. Check the highest score first.\n\nExample 1:\n```\n#include <iostream>\n#include <string>\n#include <vector>\nusing namespace std;\n\nint main() {\n    int score = 86;\n    if (score >= 90) {\n        cout << ("A") << endl;\n    } else if (score >= 80) {\n        cout << ("B") << endl;\n    } else if (score >= 70) {\n        cout << ("C") << endl;\n    } else {\n        cout << ("F") << endl;\n    }\n    return 0;\n}\n```\nOutput:\n```\nB\n```\n\nExample 2:\n```\n#include <iostream>\n#include <string>\n#include <vector>\nusing namespace std;\n\nint main() {\n    vector<int> marks = {80, 90, 70};\n    int sum = 0;\n    for (int m : marks) {\n        sum += m;\n    }\n    cout << ("Average: ") << ((sum / marks.size())) << endl;\n    return 0;\n}\n```\nOutput:\n```\nAverage: 80\n```\n\nPractice: change the numbers or words in Example 1, then guess the new output before you run it.'),
(493,17,48,'Reading error messages','An **error message** tells you what went wrong and **which line**. Read the first message first, fix it, then run again. Typical errors are a **missing semicolon**, a **misspelled name** and **mixed types**.\n\nExample 1:\n```\n#include <iostream>\n#include <string>\n#include <vector>\nusing namespace std;\n\nint main() {\n    int count = 3;\n    cout << ("Count is ") << (count) << endl;\n    // A missing semicolon on the line above would give an error\n    return 0;\n}\n```\nOutput:\n```\nCount is 3\n```\n\nExample 2:\n```\n#include <iostream>\n#include <string>\n#include <vector>\nusing namespace std;\n\nint main() {\n    string name = "Ana";\n    cout << ("Hello ") << (name) << endl;\n    // Writing nam instead of name would give an unknown name error\n    return 0;\n}\n```\nOutput:\n```\nHello Ana\n```\n\nPractice: change the numbers or words in Example 1, then guess the new output before you run it.'),
(494,17,49,'Debugging basics','**Debugging** means finding and fixing mistakes. A great trick is to **print** the values while the program runs.\n\nExample 1:\n```\n#include <iostream>\n#include <string>\n#include <vector>\nusing namespace std;\n\nint main() {\n    int total = 0;\n    for (int i = 1; i <= 3; i++) {\n        total += i;\n        cout << ("i = ") << (i) << (" total = ") << (total) << endl;\n    }\n    cout << (total) << endl;\n    return 0;\n}\n```\nOutput:\n```\ni = 1 total = 1\ni = 2 total = 3\ni = 3 total = 6\n6\n```\n\nExample 2:\n```\n#include <iostream>\n#include <string>\n#include <vector>\nusing namespace std;\n\nint main() {\n    int a = 6;\n    int b = 4;\n    cout << ("a is ") << (a) << endl;\n    cout << ("b is ") << (b) << endl;\n    cout << ("a - b is ") << (a - b) << endl;\n    return 0;\n}\n```\nOutput:\n```\na is 6\nb is 4\na - b is 2\n```\n\nExample 3:\n```\n#include <iostream>\n#include <string>\n#include <vector>\nusing namespace std;\n\nint main() {\n    int total = 0;\n    for (int i = 1; i <= 4; i++) {\n        total += i;\n        cout << ("i = ") << (i) << (" total = ") << (total) << endl;\n    }\n    cout << (total) << endl;\n    return 0;\n}\n```\nOutput:\n```\ni = 1 total = 1\ni = 2 total = 3\ni = 3 total = 6\ni = 4 total = 10\n10\n```\n\nPractice: change the numbers or words in Example 1, then guess the new output before you run it.'),
(495,17,50,'Mini project','Time to combine what you learned: **variables**, **loops**, **if** and **arrays** in small programs.\n\nExample 1:\n```\n#include <iostream>\n#include <string>\n#include <vector>\nusing namespace std;\n\nint main() {\n    // Mini project: multiplication table\n    int n = 4;\n    for (int i = 1; i <= 5; i++) {\n        cout << (n) << (" x ") << (i) << (" = ") << (n * i) << endl;\n    }\n    return 0;\n}\n```\nOutput:\n```\n4 x 1 = 4\n4 x 2 = 8\n4 x 3 = 12\n4 x 4 = 16\n4 x 5 = 20\n```\n\nExample 2:\n```\n#include <iostream>\n#include <string>\n#include <vector>\nusing namespace std;\n\nint main() {\n    vector<int> v = {5, 12, 8};\n    int sum = 0;\n    int big = v[0];\n    for (int x : v) {\n        sum += x;\n        if (x > big) {\n            big = x;\n        }\n    }\n    cout << ("Sum: ") << (sum) << endl;\n    cout << ("Biggest: ") << (big) << endl;\n    return 0;\n}\n```\nOutput:\n```\nSum: 25\nBiggest: 12\n```\n\nExample 3:\n```\n#include <iostream>\n#include <string>\n#include <vector>\nusing namespace std;\n\nint main() {\n    // Mini project: multiplication table\n    int n = 12;\n    for (int i = 1; i <= 6; i++) {\n        cout << (n) << (" x ") << (i) << (" = ") << (n * i) << endl;\n    }\n    return 0;\n}\n```\nOutput:\n```\n12 x 1 = 12\n12 x 2 = 24\n12 x 3 = 36\n12 x 4 = 48\n12 x 5 = 60\n12 x 6 = 72\n```\n\nPractice: change the numbers or words in Example 1, then guess the new output before you run it.'),
(496,20,1,'Functions in depth','A **function** can take several **parameters**, return a **value** and call other functions. Split a big problem into small functions.\n\nExample 1:\n```\n#include <iostream>\n#include <string>\n#include <vector>\nusing namespace std;\n\nint square(int n) {\n    return n * n;\n}\nint sumOfSquares(int a, int b) {\n    return square(a) + square(b);\n}\n\nint main() {\n    cout << (sumOfSquares(3, 4)) << endl;\n    return 0;\n}\n```\nOutput:\n```\n25\n```\n\nExample 2:\n```\n#include <iostream>\n#include <string>\n#include <vector>\nusing namespace std;\n\nint isEven(int n) {\n    if (n % 2 == 0) {\n        return 1;\n    }\n    return 0;\n}\n\nint main() {\n    cout << (isEven(8)) << endl;\n    cout << (isEven(7)) << endl;\n    return 0;\n}\n```\nOutput:\n```\n1\n0\n```\n\nExample 3:\n```\n#include <iostream>\n#include <string>\n#include <vector>\nusing namespace std;\n\nint square(int n) {\n    return n * n;\n}\nint sumOfSquares(int a, int b) {\n    return square(a) + square(b);\n}\n\nint main() {\n    cout << (sumOfSquares(6, 8)) << endl;\n    return 0;\n}\n```\nOutput:\n```\n100\n```\n\nPractice: change the numbers or words in Example 1, then guess the new output before you run it.'),
(497,20,2,'Pointers and references',NULL),
(498,20,3,'Recursion','**Recursion** solves a big problem by solving a smaller copy of it. Always write the **base case** first.\n\nExample 1:\n```\n#include <iostream>\n#include <string>\n#include <vector>\nusing namespace std;\n\nint power(int b, int e) {\n    if (e == 0) {\n        return 1;\n    }\n    return b * power(b, e - 1);\n}\n\nint main() {\n    cout << (power(2, 5)) << endl;\n    return 0;\n}\n```\nOutput:\n```\n32\n```\n\nExample 2:\n```\n#include <iostream>\n#include <string>\n#include <vector>\nusing namespace std;\n\nint sumDigits(int n) {\n    if (n < 10) {\n        return n;\n    }\n    return n % 10 + sumDigits((n / 10));\n}\n\nint main() {\n    cout << (sumDigits(1234)) << endl;\n    return 0;\n}\n```\nOutput:\n```\n10\n```\n\nExample 3:\n```\n#include <iostream>\n#include <string>\n#include <vector>\nusing namespace std;\n\nint power(int b, int e) {\n    if (e == 0) {\n        return 1;\n    }\n    return b * power(b, e - 1);\n}\n\nint main() {\n    cout << (power(2, 3)) << endl;\n    return 0;\n}\n```\nOutput:\n```\n8\n```\n\nPractice: change the numbers or words in Example 1, then guess the new output before you run it.'),
(499,20,4,'Namespaces',NULL),
(500,20,5,'Strings in depth','You can walk through a **string** one **character** at a time with its **index**, to reverse it or count things.\n\nExample 1:\n```\n#include <iostream>\n#include <string>\n#include <vector>\nusing namespace std;\n\nint main() {\n    string s = "hello";\n    string r = "";\n    for (int i = 0; i < s.length(); i++) {\n        r = s[i] + r;\n    }\n    cout << (r) << endl;\n    return 0;\n}\n```\nOutput:\n```\nolleh\n```\n\nExample 2:\n```\n#include <iostream>\n#include <string>\n#include <vector>\nusing namespace std;\n\nint main() {\n    string s = "education";\n    int c = 0;\n    for (int i = 0; i < s.length(); i++) {\n        if (s[i] == \'a\' || s[i] == \'e\' || s[i] == \'i\' || s[i] == \'o\' || s[i] == \'u\') {\n            c++;\n        }\n    }\n    cout << (c) << endl;\n    return 0;\n}\n```\nOutput:\n```\n5\n```\n\nPractice: change the numbers or words in Example 1, then guess the new output before you run it.'),
(501,20,6,'String formatting',NULL);
