(504,20,9,'Arrays in depth','You can **change** the items of an array while you loop over it, and use **nested** loops to compare items.\n\nExample 1:\n```\n#include <iostream>\n#include <string>\n#include <vector>\nusing namespace std;\n\nint main() {\n    vector<int> v = {1, 2, 3, 4};\n    for (int i = 0; i < v.size(); i++) {\n        v[i] = v[i] * 2;\n    }\n    for (int x : v) {\n        cout << (x) << endl;\n    }\n    return 0;\n}\n```\nOutput:\n```\n2\n4\n6\n8\n```\n\nExample 2:\n```\n#include <iostream>\n#include <string>\n#include <vector>\nusing namespace std;\n\nint main() {\n    vector<int> v = {4, 7, 4, 9};\n    int dups = 0;\n    for (int i = 0; i < v.size(); i++) {\n        for (int j = i + 1; j < v.size(); j++) {\n            if (v[i] == v[j]) {\n                dups++;\n            }\n        }\n    }\n    cout << (dups) << endl;\n    return 0;\n}\n```\nOutput:\n```\n1\n```\n\nExample 3:\n```\n#include <iostream>\n#include <string>\n#include <vector>\nusing namespace std;\n\nint main() {\n    vector<int> v = {1, 2, 4, 5};\n    for (int i = 0; i < v.size(); i++) {\n        v[i] = v[i] * 2;\n    }\n    for (int x : v) {\n        cout << (x) << endl;\n    }\n    return 0;\n}\n```\nOutput:\n```\n2\n4\n8\n10\n```\n\nPractice: change the numbers or words in Example 1, then guess the new output before you run it.'),
(505,20,10,'Two-dimensional arrays',NULL),
(506,20,11,'Sorting a list','**Sorting** puts items in order. **Bubble sort** compares neighbors and swaps them when they are in the wrong order.\n\nExample 1:\n```\n#include <iostream>\n#include <string>\n#include <vector>\nusing namespace std;\n\nint main() {\n    vector<int> v = {9, 3, 7, 1};\n    int n = v.size();\n    for (int i = 0; i < n - 1; i++) {\n        for (int j = 0; j < n - 1 - i; j++) {\n            if (v[j] > v[j + 1]) {\n                int t = v[j];\n                v[j] = v[j + 1];\n                v[j + 1] = t;\n            }\n        }\n    }\n    for (int x : v) {\n        cout << (x) << endl;\n    }\n    return 0;\n}\n```\nOutput:\n```\n1\n3\n7\n9\n```\n\nExample 2:\n```\n#include <iostream>\n#include <string>\n#include <vector>\nusing namespace std;\n\nint main() {\n    vector<int> v = {4, 8, 2, 6};\n    int n = v.size();\n    for (int i = 0; i < n - 1; i++) {\n        for (int j = 0; j < n - 1 - i; j++) {\n            if (v[j] < v[j + 1]) {\n                int t = v[j];\n                v[j] = v[j + 1];\n                v[j + 1] = t;\n            }\n        }\n    }\n    for (int x : v) {\n        cout << (x) << endl;\n    }\n    return 0;\n}\n```\nOutput:\n```\n8\n6\n4\n2\n```\n\nExample 3:\n```\n#include <iostream>\n#include <string>\n#include <vector>\nusing namespace std;\n\nint main() {\n    vector<int> v = {4, 11, 3, 1};\n    int n = v.size();\n    for (int i = 0; i < n - 1; i++) {\n        for (int j = 0; j < n - 1 - i; j++) {\n            if (v[j] > v[j + 1]) {\n                int t = v[j];\n                v[j] = v[j + 1];\n                v[j + 1] = t;\n            }\n        }\n    }\n    for (int x : v) {\n        cout << (x) << endl;\n    }\n    return 0;\n}\n```\nOutput:\n```\n1\n3\n4\n11\n```\n\nPractice: change the numbers or words in Example 1, then guess the new output before you run it.'),
(507,20,12,'Searching a list','**Linear search** checks the items one by one from the start until it finds the target.\n\nExample 1:\n```\n#include <iostream>\n#include <string>\n#include <vector>\nusing namespace std;\n\nint main() {\n    vector<int> v = {5, 8, 2, 9};\n    int target = 2;\n    int idx = -1;\n    for (int i = 0; i < v.size(); i++) {\n        if (v[i] == target) {\n            idx = i;\n        }\n    }\n    cout << (idx) << endl;\n    return 0;\n}\n```\nOutput:\n```\n2\n```\n\nExample 2:\n```\n#include <iostream>\n#include <string>\n#include <vector>\nusing namespace std;\n\nint main() {\n    vector<int> v = {3, 6, 3, 8, 3};\n    int count = 0;\n    for (int x : v) {\n        if (x == 3) {\n            count++;\n        }\n    }\n    cout << (count) << endl;\n    return 0;\n}\n```\nOutput:\n```\n3\n```\n\nPractice: change the numbers or words in Example 1, then guess the new output before you run it.'),
