(544,20,49,'Sorting algorithms intro','**Selection sort** finds the smallest item and moves it to the front, then repeats for the rest.\n\nExample 1:\n```\n#include <iostream>\n#include <string>\n#include <vector>\nusing namespace std;\n\nint main() {\n    vector<int> v = {5, 2, 9, 1};\n    int n = v.size();\n    for (int i = 0; i < n - 1; i++) {\n        int small = i;\n        for (int j = i + 1; j < n; j++) {\n            if (v[j] < v[small]) {\n                small = j;\n            }\n        }\n        int t = v[i];\n        v[i] = v[small];\n        v[small] = t;\n    }\n    for (int x : v) {\n        cout << (x) << endl;\n    }\n    return 0;\n}\n```\nOutput:\n```\n1\n2\n5\n9\n```\n\nExample 2:\n```\n#include <iostream>\n#include <string>\n#include <vector>\nusing namespace std;\n\nint main() {\n    vector<int> v = {30, 10, 20};\n    int n = v.size();\n    for (int i = 0; i < n - 1; i++) {\n        int small = i;\n        for (int j = i + 1; j < n; j++) {\n            if (v[j] < v[small]) {\n                small = j;\n            }\n        }\n        int t = v[i];\n        v[i] = v[small];\n        v[small] = t;\n    }\n    cout << (v[0]) << (" ") << (v[1]) << (" ") << (v[2]) << endl;\n    return 0;\n}\n```\nOutput:\n```\n10 20 30\n```\n\nExample 3:\n```\n#include <iostream>\n#include <string>\n#include <vector>\nusing namespace std;\n\nint main() {\n    vector<int> v = {9, 2, 4, 1};\n    int n = v.size();\n    for (int i = 0; i < n - 1; i++) {\n        int small = i;\n        for (int j = i + 1; j < n; j++) {\n            if (v[j] < v[small]) {\n                small = j;\n            }\n        }\n        int t = v[i];\n        v[i] = v[small];\n        v[small] = t;\n    }\n    for (int x : v) {\n        cout << (x) << endl;\n    }\n    return 0;\n}\n```\nOutput:\n```\n1\n2\n4\n9\n```\n\nPractice: change the numbers or words in Example 1, then guess the new output before you run it.'),
(545,20,50,'Mini project','A small **grade book**: add up the scores, find the average and count how many students **passed**.\n\nExample 1:\n```\n#include <iostream>\n#include <string>\n#include <vector>\nusing namespace std;\n\nint main() {\n    vector<int> scores = {70, 85, 90, 65};\n    int sum = 0;\n    int pass = 0;\n    for (int s : scores) {\n        sum += s;\n        if (s >= 70) {\n            pass++;\n        }\n    }\n    cout << ("Average: ") << ((sum / scores.size())) << endl;\n    cout << ("Passed: ") << (pass) << endl;\n    return 0;\n}\n```\nOutput:\n```\nAverage: 77\nPassed: 3\n```\n\nExample 2:\n```\n#include <iostream>\n#include <string>\n#include <vector>\nusing namespace std;\n\nint main() {\n    vector<int> v = {4, 9, 6};\n    int big = v[0];\n    int total = 0;\n    for (int x : v) {\n        total += x;\n        if (x > big) {\n            big = x;\n        }\n    }\n    cout << ("Total: ") << (total) << endl;\n    cout << ("Largest: ") << (big) << endl;\n    return 0;\n}\n```\nOutput:\n```\nTotal: 19\nLargest: 9\n```\n\nExample 3:\n```\n#include <iostream>\n#include <string>\n#include <vector>\nusing namespace std;\n\nint main() {\n    vector<int> scores = {6, 4, 8, 9};\n    int sum = 0;\n    int pass = 0;\n    for (int s : scores) {\n        sum += s;\n        if (s >= 6) {\n            pass++;\n        }\n    }\n    cout << ("Average: ") << ((sum / scores.size())) << endl;\n    cout << ("Passed: ") << (pass) << endl;\n    return 0;\n}\n```\nOutput:\n```\nAverage: 6\nPassed: 3\n```\n\nPractice: change the numbers or words in Example 1, then guess the new output before you run it.'),
