INSERT INTO `new_challenges`(id,language,level,title,buggy_code,hint,expected_output) VALUES
(51,'python','Easy','Wrong operator #1','print(7 - 3)','Which symbol adds numbers?','10'),
(52,'python','Easy','Numbers and text #1','age = 18\nprint("Age: " + age)','Text and numbers cannot be joined with + directly.','Age: 18'),
(53,'python','Easy','Make it loud #1','word = "hello"\nprint(word.lower())','Which string method gives capital letters?','HELLO'),
(54,'python','Easy','Last fruit #1','fruits = ["apple", "mango", "kiwi"]\nprint(fruits[3])','Negative indexes count from the end.','kiwi'),
(55,'python','Easy','Count from one #1','for i in range(0, 4):\n    print(i)','range() starts at its first argument.','1\n2\n3'),
(56,'python','Easy','Sum to a number #1','n = 5\ntotal = 0\nfor i in range(1, n):\n    total += i\nprint(total)','range() stops before its end number.','15'),
(57,'python','Easy','Missing bracket #1','name = "Ana"\nprint("Hello, " + name','Count the opening and closing brackets.','Hello, Ana'),
(58,'python','Easy','Wrong operator #2','print(38 - 31)','Which symbol adds numbers?','69'),
(59,'python','Easy','Numbers and text #2','age = 32\nprint("Age: " + age)','Text and numbers cannot be joined with + directly.','Age: 32'),
(60,'python','Easy','Make it loud #2','word = "howdy"\nprint(word.lower())','Which string method gives capital letters?','HOWDY'),
