(202,'python','Advanced','Shared class list #1','class Bag:\n    items = []\n    def add(self, x):\n        self.items.append(x)\n\na, b = Bag(), Bag()\na.add(1)\nprint(len(b.items))','Give every object its own list in __init__.','0'),
(203,'python','Advanced','Decorator result #1','def loud(f):\n    def wrap(*a):\n        f(*a).upper()\n    return wrap\n\n@loud\ndef hi(name):\n    return "hi " + name\n\nprint(hi("ana"))','The wrapper must return what the function returns.','HI ANA'),
(204,'python','Advanced','Closure counter #1','def make():\n    n = 0\n    def inc():\n        n += 1\n        return n\n    return inc\n\nc = make()\nc()\nprint(c())','Assigning to an outer variable needs nonlocal.','2'),
(205,'python','Advanced','Memoized Fibonacci #1','memo = {}\ndef fib(n):\n    if n < 2:\n        return n\n    if n not in memo:\n        memo[n] = fib(n - 1) + fib(n - 2)\n    return fib(n)\nprint(fib(30))','Return the stored value, not another call.','832040'),
(206,'python','Advanced','Used-up generator #2','gen = (n * n for n in range(40))\nprint(sum(gen))\nprint(sum(gen))','A generator can only be read once.','20540\n20540'),
