(401,'javascript','Advanced','Forgotten await #1','const wait = ms => new Promise(r => setTimeout(r, ms));\nasync function load() {\n  await wait(10);\n  return 5;\n}\n(async () => {\n  const v = load();\n  console.log(v + 1);\n})()','An async function returns a promise. Wait for it.','6'),
(402,'javascript','Advanced','Wait for all #1','const p = n => new Promise(r => setTimeout(() => r(n), 10));\n(async () => {\n  const r = [p(1), p(2)];\n  console.log(r.join("+"));\n})()','Promise.all turns promises into their values.','1+2'),
(403,'javascript','Advanced','Lost this #1','class Stack {\n  constructor() { this.items = []; }\n  push(x) { items.push(x); return this; }\n  size() { return this.items.length; }\n}\nconsole.log(new Stack().push(1).push(2).size());','Properties live on this inside a class.','2'),
(404,'javascript','Advanced','Sort by age #1','const people = [{ n: "Ana", a: 30 }, { n: "Ben", a: 25 }];\npeople.sort((x, y) => x.n - y.n);\nconsole.log(people.map(p => p.n).join(","));','Subtract the numbers, not the names.','Ben,Ana'),
(405,'javascript','Advanced','Safe lookup #1','const cfg = { db: null };\nconsole.log(cfg.db.host ?? "none");','?. stops when a value is null.','none'),
