(436,'javascript','Advanced','Wait for all #12','const p = n => new Promise(r => setTimeout(() => r(n), 8));\n(async () => {\n  const r = [p(1), p(2)];\n  console.log(r.join("+"));\n})()','Promise.all turns promises into their values.','1+2'),
