INSERT INTO `new_challenges`(id,language,level,title,buggy_code,hint,expected_output) VALUES
(481,'cpp','Easy','Missing semicolon #1','#include <iostream>\n#include <string>\n#include <vector>\nusing namespace std;\n\nint main() {\n    cout << ("chair") << endl\n    return 0;\n}\n','Every statement ends with a semicolon.','chair'),
(482,'csharp','Easy','Missing semicolon #1','Console.WriteLine("chair")\n','Every statement ends with a semicolon.','chair'),
(483,'php','Easy','Missing semicolon #1','<?php\necho ("chair") . PHP_EOL\n','Every statement ends with a semicolon.','chair'),
(484,'cpp','Easy','Wrong operator #1','#include <iostream>\n#include <string>\n#include <vector>\nusing namespace std;\n\nint main() {\n    int a = 6;\n    int b = 14;\n    cout << (a - b) << endl;\n    return 0;\n}\n','Which symbol adds numbers?','20'),
