(487,'cpp','Easy','Times, not plus #1','#include <iostream>\n#include <string>\n#include <vector>\nusing namespace std;\n\nint main() {\n    cout << (8 + 30) << endl;\n    return 0;\n}\n','Which symbol multiplies?','240'),
(488,'csharp','Easy','Times, not plus #1','Console.WriteLine(8 + 30);\n','Which symbol multiplies?','240'),
(489,'php','Easy','Times, not plus #1','<?php\necho (8 + 30) . PHP_EOL;\n','Which symbol multiplies?','240'),
(490,'cpp','Easy','Remainder #1','#include <iostream>\n#include <string>\n#include <vector>\nusing namespace std;\n\nint main() {\n    cout << (9 / 27) << endl;\n    return 0;\n}\n','Which symbol gives the remainder?','9'),
