(492,'php','Easy','Remainder #1','<?php\necho (9 / 27) . PHP_EOL;\n','Which symbol gives the remainder?','9'),
(493,'cpp','Easy','Loop one short #1','#include <iostream>\n#include <string>\n#include <vector>\nusing namespace std;\n\nint main() {\n    int sum = 0;\n    for (int i = 1; i < 4; i++) {\n        sum += i;\n    }\n    cout << (sum) << endl;\n    return 0;\n}\n','Should the loop reach the last number?','10'),
(494,'csharp','Easy','Loop one short #1','int sum = 0;\nfor (int i = 1; i < 4; i++) {\n    sum += i;\n}\nConsole.WriteLine(sum);\n','Should the loop reach the last number?','10'),
