(499,'cpp','Easy','Wrong variable #1','#include <iostream>\n#include <string>\n#include <vector>\nusing namespace std;\n\nint main() {\n    int a = 3;\n    int b = 26;\n    cout << (a) << endl;\n    return 0;\n}\n','The program should print the second number.','26'),
