(790,'cpp','Hard','Prime check #1','#include <iostream>\n#include <string>\n#include <vector>\nusing namespace std;\n\nint isPrime(int n) {\n    if (n < 2) {\n        return 0;\n    }\n    for (int i = 2; i * i <= n; i++) {\n        if (n % i == 0) {\n            return 1;\n        }\n    }\n    return 1;\n}\n\nint main() {\n    cout << (isPrime(30)) << endl;\n    return 0;\n}\n','A number with a divisor is not prime.','0'),
