(917,'csharp','Hard','Sum of digits #6','int digitSum(int n) {\n    int s = 0;\n    while (n > 0) {\n        s += n % 10;\n        n = (n / 100);\n    }\n    return s;\n}\n\nConsole.WriteLine(digitSum(9899));\n','Remove one digit at a time.','35'),
(918,'php','Hard','Sum of digits #6','<?php\nfunction digitSum($n) {\n    $s = 0;\n    while ($n > 0) {\n        $s += $n % 10;\n        $n = intdiv($n, 100);\n    }\n    return $s;\n}\n\necho (digitSum(9899)) . PHP_EOL;\n','Remove one digit at a time.','35'),
(919,'cpp','Hard','Fizz buzz #5','#include <iostream>\n#include <string>\n#include <vector>\nusing namespace std;\n\nint main() {\n    for (int i = 1; i <= 16; i++) {\n        if (i % 3 == 0 || i % 5 == 0) {\n            cout << ("both") << endl;\n        } else if (i % 3 == 0) {\n            cout << ("three") << endl;\n        } else if (i % 5 == 0) {\n            cout << ("five") << endl;\n        } else {\n            cout << (i) << endl;\n        }\n    }\n    return 0;\n}\n','Both rules must be true for both.','1\n2\nthree\n4\nfive\nthree\n7\n8\nthree\nfive\n11\nthree\n13\n14\nboth\n16'),
(920,'csharp','Hard','Fizz buzz #5','for (int i = 1; i <= 16; i++) {\n    if (i % 3 == 0 || i % 5 == 0) {\n        Console.WriteLine("both");\n    } else if (i % 3 == 0) {\n        Console.WriteLine("three");\n    } else if (i % 5 == 0) {\n        Console.WriteLine("five");\n    } else {\n        Console.WriteLine(i);\n    }\n}\n','Both rules must be true for both.','1\n2\nthree\n4\nfive\nthree\n7\n8\nthree\nfive\n11\nthree\n13\n14\nboth\n16');
