(931,'cpp','Advanced','Recursive factorial #1','#include <iostream>\n#include <string>\n#include <vector>\nusing namespace std;\n\nint fact(int n) {\n    if (n <= 1) {\n        return 1;\n    }\n    return n * fact(n + 1);\n}\n\nint main() {\n    cout << (fact(3)) << endl;\n    return 0;\n}\n','Each call must move toward 1.','6'),
