(934,'cpp','Advanced','Fibonacci #1','#include <iostream>\n#include <string>\n#include <vector>\nusing namespace std;\n\nint fib(int n) {\n    if (n < 2) {\n        return n;\n    }\n    return fib(n - 1) - fib(n - 2);\n}\n\nint main() {\n    cout << (fib(9)) << endl;\n    return 0;\n}\n','Each number is the sum of the two before it.','34'),
