(940,'cpp','Advanced','Greatest common divisor #1','#include <iostream>\n#include <string>\n#include <vector>\nusing namespace std;\n\nint gcd(int a, int b) {\n    while (b != 0) {\n        int t = b;\n        b = a % b;\n        a = b;\n    }\n    return a;\n}\n\nint main() {\n    cout << (gcd(18, 5)) << endl;\n    return 0;\n}\n','Move the old b into a.','1'),
