(943,'cpp','Advanced','Bubble sort #1','#include <iostream>\n#include <string>\n#include <vector>\nusing namespace std;\n\nint main() {\n    vector<int> v = {13, 29, 6, 18};\n    int n = v.size();\n    for (int i = 0; i < n - 1; i++) {\n        for (int j = 0; j < n - 1 - i; j++) {\n            if (v[j] < v[j + 1]) {\n                int t = v[j];\n                v[j] = v[j + 1];\n                v[j + 1] = t;\n            }\n        }\n    }\n    for (int x : v) {\n        cout << (x) << endl;\n    }\n    return 0;\n}\n','Swap when the left one is bigger.','6\n13\n18\n29'),
(944,'csharp','Advanced','Bubble sort #1','var v = new List<int> { 13, 29, 6, 18 };\nint n = v.Count;\nfor (int i = 0; i < n - 1; i++) {\n    for (int j = 0; j < n - 1 - i; j++) {\n        if (v[j] < v[j + 1]) {\n            int t = v[j];\n            v[j] = v[j + 1];\n            v[j + 1] = t;\n        }\n    }\n}\nforeach (int x in v) {\n    Console.WriteLine(x);\n}\n','Swap when the left one is bigger.','6\n13\n18\n29'),
