(994,'cpp','Advanced','Power function #3','#include <iostream>\n#include <string>\n#include <vector>\nusing namespace std;\n\nint power(int b, int e) {\n    int r = 1;\n    for (int i = 0; i < e; i++) {\n        r = r * e;\n    }\n    return r;\n}\n\nint main() {\n    cout << (power(2, 4)) << endl;\n    return 0;\n}\n','Multiply by the base each time.','16'),
