(996,'php','Advanced','Power function #3','<?php\nfunction power($b, $e) {\n    $r = 1;\n    for ($i = 0; $i < $e; $i++) {\n        $r = $r * $e;\n    }\n    return $r;\n}\n\necho (power(2, 4)) . PHP_EOL;\n','Multiply by the base each time.','16'),
(997,'cpp','Advanced','Greatest common divisor #3','#include <iostream>\n#include <string>\n#include <vector>\nusing namespace std;\n\nint gcd(int a, int b) {\n    while (b != 0) {\n        int t = b;\n        b = a % b;\n        a = b;\n    }\n    return a;\n}\n\nint main() {\n    cout << (gcd(3, 27)) << endl;\n    return 0;\n}\n','Move the old b into a.','3'),
(998,'csharp','Advanced','Greatest common divisor #3','int gcd(int a, int b) {\n    while (b != 0) {\n        int t = b;\n        b = a % b;\n        a = b;\n    }\n    return a;\n}\n\nConsole.WriteLine(gcd(3, 27));\n','Move the old b into a.','3'),
(999,'php','Advanced','Greatest common divisor #3','<?php\nfunction gcd($a, $b) {\n    while ($b != 0) {\n        $t = $b;\n        $b = $a % $b;\n        $a = $b;\n    }\n    return $a;\n}\n\necho (gcd(3, 27)) . PHP_EOL;\n','Move the old b into a.','3'),
(1000,'cpp','Advanced','Bubble sort #3','#include <iostream>\n#include <string>\n#include <vector>\nusing namespace std;\n\nint main() {\n    vector<int> v = {5, 25, 17, 13};\n    int n = v.size();\n    for (int i = 0; i < n - 1; i++) {\n        for (int j = 0; j < n - 1 - i; j++) {\n            if (v[j] < v[j + 1]) {\n                int t = v[j];\n                v[j] = v[j + 1];\n                v[j + 1] = t;\n            }\n        }\n    }\n    for (int x : v) {\n        cout << (x) << endl;\n    }\n    return 0;\n}\n','Swap when the left one is bigger.','5\n13\n17\n25');
