(1054,'cpp','Advanced','Bubble sort #5','#include <iostream>\n#include <string>\n#include <vector>\nusing namespace std;\n\nint main() {\n    vector<int> v = {8, 6, 23, 25};\n    int n = v.size();\n    for (int i = 0; i < n - 1; i++) {\n        for (int j = 0; j < n - 1 - i; j++) {\n            if (v[j] < v[j + 1]) {\n                int t = v[j];\n                v[j] = v[j + 1];\n                v[j + 1] = t;\n            }\n        }\n    }\n    for (int x : v) {\n        cout << (x) << endl;\n    }\n    return 0;\n}\n','Swap when the left one is bigger.','6\n8\n23\n25'),
(1055,'csharp','Advanced','Bubble sort #5','var v = new List<int> { 8, 6, 23, 25 };\nint n = v.Count;\nfor (int i = 0; i < n - 1; i++) {\n    for (int j = 0; j < n - 1 - i; j++) {\n        if (v[j] < v[j + 1]) {\n            int t = v[j];\n            v[j] = v[j + 1];\n            v[j + 1] = t;\n        }\n    }\n}\nforeach (int x in v) {\n    Console.WriteLine(x);\n}\n','Swap when the left one is bigger.','6\n8\n23\n25'),
(1056,'php','Advanced','Bubble sort #5','<?php\n$v = [8, 6, 23, 25];\n$n = count($v);\nfor ($i = 0; $i < $n - 1; $i++) {\n    for ($j = 0; $j < $n - 1 - $i; $j++) {\n        if ($v[$j] < $v[$j + 1]) {\n            $t = $v[$j];\n            $v[$j] = $v[$j + 1];\n            $v[$j + 1] = $t;\n        }\n    }\n}\nforeach ($v as $x) {\n    echo ($x) . PHP_EOL;\n}\n','Swap when the left one is bigger.','6\n8\n23\n25'),
(1057,'cpp','Advanced','Linear search #5','#include <iostream>\n#include <string>\n#include <vector>\nusing namespace std;\n\nint main() {\n    vector<int> v = {21, 3, 17, 11};\n    int idx = -1;\n    for (int i = 0; i < v.size(); i++) {\n        if (v[i] == 17) {\n            idx = i;\n        }\n    }\n    cout << (i) << endl;\n    return 0;\n}\n','The index is saved in idx.','2'),
(1058,'csharp','Advanced','Linear search #5','var v = new List<int> { 21, 3, 17, 11 };\nint idx = -1;\nfor (int i = 0; i < v.Count; i++) {\n    if (v[i] == 17) {\n        idx = i;\n    }\n}\nConsole.WriteLine(i);\n','The index is saved in idx.','2'),
(1059,'php','Advanced','Linear search #5','<?php\n$v = [21, 3, 17, 11];\n$idx = -1;\nfor ($i = 0; $i < count($v); $i++) {\n    if ($v[$i] == 17) {\n        $idx = $i;\n    }\n}\necho ($i) . PHP_EOL;\n','The index is saved in idx.','2'),
(1060,'cpp','Advanced','Count a letter #5','#include <iostream>\n#include <string>\n#include <vector>\nusing namespace std;\n\nint main() {\n    string s = "stone";\n    int c = 0;\n    for (int i = 0; i < s.length(); i++) {\n        if (s[i] == \'o\') {\n            c;\n        }\n    }\n    cout << (c) << endl;\n    return 0;\n}\n','Increase the counter when the letter matches.','1'),
(1061,'csharp','Advanced','Count a letter #5','string s = "stone";\nint c = 0;\nfor (int i = 0; i < s.Length; i++) {\n    if (s[i] == \'o\') {\n        c;\n    }\n}\nConsole.WriteLine(c);\n','Increase the counter when the letter matches.','1'),
(1062,'php','Advanced','Count a letter #5','<?php\n$s = "stone";\n$c = 0;\nfor ($i = 0; $i < strlen($s); $i++) {\n    if ($s[$i] == \'o\') {\n        $c;\n    }\n}\necho ($c) . PHP_EOL;\n','Increase the counter when the letter matches.','1'),
(1063,'cpp','Advanced','Sum of squares #5','#include <iostream>\n#include <string>\n#include <vector>\nusing namespace std;\n\nint main() {\n    int t = 0;\n    for (int i = 1; i <= 7; i++) {\n        t += i + i;\n    }\n    cout << (t) << endl;\n    return 0;\n}\n','A square is a number times itself.','140'),
(1064,'csharp','Advanced','Sum of squares #5','int t = 0;\nfor (int i = 1; i <= 7; i++) {\n    t += i + i;\n}\nConsole.WriteLine(t);\n','A square is a number times itself.','140'),
(1065,'php','Advanced','Sum of squares #5','<?php\n$t = 0;\nfor ($i = 1; $i <= 7; $i++) {\n    $t += $i + $i;\n}\necho ($t) . PHP_EOL;\n','A square is a number times itself.','140'),
(1066,'cpp','Advanced','Every other item #5','#include <iostream>\n#include <string>\n#include <vector>\nusing namespace std;\n\nint main() {\n    vector<int> v = {20, 14, 18, 12, 3};\n    int t = 0;\n    for (int i = 0; i < v.size(); i++) {\n        t += v[i];\n    }\n    cout << (t) << endl;\n    return 0;\n}\n','Jump two positions each step.','41'),
(1067,'csharp','Advanced','Every other item #5','var v = new List<int> { 20, 14, 18, 12, 3 };\nint t = 0;\nfor (int i = 0; i < v.Count; i++) {\n    t += v[i];\n}\nConsole.WriteLine(t);\n','Jump two positions each step.','41'),
(1068,'php','Advanced','Every other item #5','<?php\n$v = [20, 14, 18, 12, 3];\n$t = 0;\nfor ($i = 0; $i < count($v); $i++) {\n    $t += $v[$i];\n}\necho ($t) . PHP_EOL;\n','Jump two positions each step.','41'),
(1069,'cpp','Advanced','Recursive factorial #5','#include <iostream>\n#include <string>\n#include <vector>\nusing namespace std;\n\nint fact(int n) {\n    if (n <= 1) {\n        return 1;\n    }\n    return n * fact(n + 1);\n}\n\nint main() {\n    cout << (fact(8)) << endl;\n    return 0;\n}\n','Each call must move toward 1.','40320'),
(1070,'csharp','Advanced','Recursive factorial #5','int fact(int n) {\n    if (n <= 1) {\n        return 1;\n    }\n    return n * fact(n + 1);\n}\n\nConsole.WriteLine(fact(8));\n','Each call must move toward 1.','40320'),
(1071,'php','Advanced','Recursive factorial #5','<?php\nfunction fact($n) {\n    if ($n <= 1) {\n        return 1;\n    }\n    return $n * fact($n + 1);\n}\n\necho (fact(8)) . PHP_EOL;\n','Each call must move toward 1.','40320'),
(1072,'cpp','Advanced','Power function #6','#include <iostream>\n#include <string>\n#include <vector>\nusing namespace std;\n\nint power(int b, int e) {\n    int r = 1;\n    for (int i = 0; i < e; i++) {\n        r = r * e;\n    }\n    return r;\n}\n\nint main() {\n    cout << (power(3, 8)) << endl;\n    return 0;\n}\n','Multiply by the base each time.','6561'),
(1073,'csharp','Advanced','Power function #6','int power(int b, int e) {\n    int r = 1;\n    for (int i = 0; i < e; i++) {\n        r = r * e;\n    }\n    return r;\n}\n\nConsole.WriteLine(power(3, 8));\n','Multiply by the base each time.','6561'),
(1074,'php','Advanced','Power function #6','<?php\nfunction power($b, $e) {\n    $r = 1;\n    for ($i = 0; $i < $e; $i++) {\n        $r = $r * $e;\n    }\n    return $r;\n}\n\necho (power(3, 8)) . PHP_EOL;\n','Multiply by the base each time.','6561'),
(1075,'cpp','Advanced','Greatest common divisor #6','#include <iostream>\n#include <string>\n#include <vector>\nusing namespace std;\n\nint gcd(int a, int b) {\n    while (b != 0) {\n        int t = b;\n        b = a % b;\n        a = b;\n    }\n    return a;\n}\n\nint main() {\n    cout << (gcd(28, 15)) << endl;\n    return 0;\n}\n','Move the old b into a.','1'),
(1076,'csharp','Advanced','Greatest common divisor #6','int gcd(int a, int b) {\n    while (b != 0) {\n        int t = b;\n        b = a % b;\n        a = b;\n    }\n    return a;\n}\n\nConsole.WriteLine(gcd(28, 15));\n','Move the old b into a.','1'),
(1077,'php','Advanced','Greatest common divisor #6','<?php\nfunction gcd($a, $b) {\n    while ($b != 0) {\n        $t = $b;\n        $b = $a % $b;\n        $a = $b;\n    }\n    return $a;\n}\n\necho (gcd(28, 15)) . PHP_EOL;\n','Move the old b into a.','1'),
(1078,'cpp','Advanced','Bubble sort #6','#include <iostream>\n#include <string>\n#include <vector>\nusing namespace std;\n\nint main() {\n    vector<int> v = {25, 19, 15, 28};\n    int n = v.size();\n    for (int i = 0; i < n - 1; i++) {\n        for (int j = 0; j < n - 1 - i; j++) {\n            if (v[j] < v[j + 1]) {\n                int t = v[j];\n                v[j] = v[j + 1];\n                v[j + 1] = t;\n            }\n        }\n    }\n    for (int x : v) {\n        cout << (x) << endl;\n    }\n    return 0;\n}\n','Swap when the left one is bigger.','15\n19\n25\n28'),
(1079,'csharp','Advanced','Bubble sort #6','var v = new List<int> { 25, 19, 15, 28 };\nint n = v.Count;\nfor (int i = 0; i < n - 1; i++) {\n    for (int j = 0; j < n - 1 - i; j++) {\n        if (v[j] < v[j + 1]) {\n            int t = v[j];\n            v[j] = v[j + 1];\n            v[j + 1] = t;\n        }\n    }\n}\nforeach (int x in v) {\n    Console.WriteLine(x);\n}\n','Swap when the left one is bigger.','15\n19\n25\n28'),
(1080,'php','Advanced','Bubble sort #6','<?php\n$v = [25, 19, 15, 28];\n$n = count($v);\nfor ($i = 0; $i < $n - 1; $i++) {\n    for ($j = 0; $j < $n - 1 - $i; $j++) {\n        if ($v[$j] < $v[$j + 1]) {\n            $t = $v[$j];\n            $v[$j] = $v[$j + 1];\n            $v[$j + 1] = $t;\n        }\n    }\n}\nforeach ($v as $x) {\n    echo ($x) . PHP_EOL;\n}\n','Swap when the left one is bigger.','15\n19\n25\n28');
