(1349,'html','Medium','Pixel unit #4','h1 { font-size: 8; }','A size needs a unit.','HTML:{"has": ["h1 { font-size: 8px; }"], "not": ["h1 { font-size: 8; }"]}'),
(1350,'html','Medium','Pixel unit #5','h1 { font-size: 20; }','A size needs a unit.','HTML:{"has": ["h1 { font-size: 20px; }"], "not": ["h1 { font-size: 20; }"]}'),
(1351,'html','Medium','Background color #1','body { background-colour: gray; }','The property is background-color.','HTML:{"has": ["body { background-color: gray; }"], "not": ["body { background-colour: gray; }"]}'),
(1352,'html','Medium','Background color #2','body { background-colour: brown; }','The property is background-color.','HTML:{"has": ["body { background-color: brown; }"], "not": ["body { background-colour: brown; }"]}'),
(1353,'html','Medium','Background color #3','body { background-colour: pink; }','The property is background-color.','HTML:{"has": ["body { background-color: pink; }"], "not": ["body { background-colour: pink; }"]}'),
(1354,'html','Medium','Background color #4','body { background-colour: red; }','The property is background-color.','HTML:{"has": ["body { background-color: red; }"], "not": ["body { background-colour: red; }"]}'),
(1355,'html','Medium','Background color #5','body { background-colour: navy; }','The property is background-color.','HTML:{"has": ["body { background-color: navy; }"], "not": ["body { background-colour: navy; }"]}'),
(1356,'html','Medium','ID selector #1','<style>\n  .main { color: blue; }\n</style>\n<div id="main">lake</div>','An id selector starts with #.','HTML:{"has": ["#main { color: blue; }"], "not": [".main { color: blue; }"]}'),
(1357,'html','Medium','ID selector #2','<style>\n  .main { color: purple; }\n</style>\n<div id="main">sun</div>','An id selector starts with #.','HTML:{"has": ["#main { color: purple; }"], "not": [".main { color: purple; }"]}'),
(1358,'html','Medium','ID selector #3','<style>\n  .main { color: red; }\n</style>\n<div id="main">bird</div>','An id selector starts with #.','HTML:{"has": ["#main { color: red; }"], "not": [".main { color: red; }"]}'),
(1359,'html','Medium','ID selector #4','<style>\n  .main { color: orange; }\n</style>\n<div id="main">moon</div>','An id selector starts with #.','HTML:{"has": ["#main { color: orange; }"], "not": [".main { color: orange; }"]}'),
(1360,'html','Medium','ID selector #5','<style>\n  .main { color: blue; }\n</style>\n<div id="main">star</div>','An id selector starts with #.','HTML:{"has": ["#main { color: blue; }"], "not": [".main { color: blue; }"]}');
INSERT INTO `new_challenges`(id,language,level,title,buggy_code,hint,expected_output) VALUES
(1361,'html','Medium','Border style #1','div { border: 2px soild purple; }','Check the spelling of solid.','HTML:{"has": ["div { border: 2px solid purple; }"], "not": ["div { border: 2px soild purple; }"]}'),
(1362,'html','Medium','Border style #2','div { border: 2px soild brown; }','Check the spelling of solid.','HTML:{"has": ["div { border: 2px solid brown; }"], "not": ["div { border: 2px soild brown; }"]}'),
(1363,'html','Medium','Border style #3','div { border: 2px soild gray; }','Check the spelling of solid.','HTML:{"has": ["div { border: 2px solid gray; }"], "not": ["div { border: 2px soild gray; }"]}'),
(1364,'html','Medium','Border style #4','div { border: 2px soild navy; }','Check the spelling of solid.','HTML:{"has": ["div { border: 2px solid navy; }"], "not": ["div { border: 2px soild navy; }"]}'),
(1365,'html','Medium','Border style #5','div { border: 2px soild teal; }','Check the spelling of solid.','HTML:{"has": ["div { border: 2px solid teal; }"], "not": ["div { border: 2px soild teal; }"]}'),
(1366,'html','Medium','Text align #1','h1 { text-align: centre; }','The value is center.','HTML:{"has": ["h1 { text-align: center; }"], "not": ["h1 { text-align: centre; }"]}'),
(1367,'html','Medium','Margin property #1','p { margins: 28px; }','The property is margin.','HTML:{"has": ["p { margin: 28px; }"], "not": ["p { margins: 28px; }"]}'),
(1368,'html','Medium','Margin property #2','p { margins: 32px; }','The property is margin.','HTML:{"has": ["p { margin: 32px; }"], "not": ["p { margins: 32px; }"]}'),
(1369,'html','Medium','Margin property #3','p { margins: 20px; }','The property is margin.','HTML:{"has": ["p { margin: 20px; }"], "not": ["p { margins: 20px; }"]}'),
(1370,'html','Medium','Margin property #4','p { margins: 24px; }','The property is margin.','HTML:{"has": ["p { margin: 24px; }"], "not": ["p { margins: 24px; }"]}'),
(1371,'html','Medium','Margin property #5','p { margins: 12px; }','The property is margin.','HTML:{"has": ["p { margin: 12px; }"], "not": ["p { margins: 12px; }"]}'),
(1372,'html','Medium','Font weight #1','p { font-weight: heavy; }','Bold text uses the value bold.','HTML:{"has": ["p { font-weight: bold; }"], "not": ["p { font-weight: heavy; }"]}'),
(1373,'html','Hard','Flex display #1','.row { display: flexbox; gap: 8px; }','The value is flex.','HTML:{"has": [".row { display: flex; gap: 8px; }"], "not": [".row { display: flexbox; gap: 8px; }"]}'),
(1374,'html','Hard','Flex display #2','.row { display: flexbox; gap: 40px; }','The value is flex.','HTML:{"has": [".row { display: flex; gap: 40px; }"], "not": [".row { display: flexbox; gap: 40px; }"]}'),
(1375,'html','Hard','Flex display #3','.row { display: flexbox; gap: 32px; }','The value is flex.','HTML:{"has": [".row { display: flex; gap: 32px; }"], "not": [".row { display: flexbox; gap: 32px; }"]}'),
(1376,'html','Hard','Flex display #4','.row { display: flexbox; gap: 16px; }','The value is flex.','HTML:{"has": [".row { display: flex; gap: 16px; }"], "not": [".row { display: flexbox; gap: 16px; }"]}'),
(1377,'html','Hard','Flex display #5','.row { display: flexbox; gap: 20px; }','The value is flex.','HTML:{"has": [".row { display: flex; gap: 20px; }"], "not": [".row { display: flexbox; gap: 20px; }"]}'),
(1378,'html','Hard','Center items #1','.row { justify-content: middle; }','The value is center.','HTML:{"has": [".row { justify-content: center; }"], "not": [".row { justify-content: middle; }"]}'),
(1379,'html','Hard','Grid columns #1','.grid { display: grid; grid-template-columns: repeat(3 1fr); }','Separate values with commas.','HTML:{"has": [".grid { display: grid; grid-template-columns: repeat(3, 1fr); }"], "not": [".grid { display: grid; grid-template-columns: repeat(3 1fr); }"]}'),
(1380,'html','Hard','Input type #1','<input type="txt" name="book">','The type for text is text.','HTML:{"has": ["<input type=\\"text\\" name=\\"book\\">"], "not": ["<input type=\\"txt\\" name=\\"book\\">"]}'),
(1381,'html','Hard','Input type #2','<input type="txt" name="fish">','The type for text is text.','HTML:{"has": ["<input type=\\"text\\" name=\\"fish\\">"], "not": ["<input type=\\"txt\\" name=\\"fish\\">"]}'),
(1382,'html','Hard','Input type #3','<input type="txt" name="star">','The type for text is text.','HTML:{"has": ["<input type=\\"text\\" name=\\"star\\">"], "not": ["<input type=\\"txt\\" name=\\"star\\">"]}'),
(1383,'html','Hard','Input type #4','<input type="txt" name="cat">','The type for text is text.','HTML:{"has": ["<input type=\\"text\\" name=\\"cat\\">"], "not": ["<input type=\\"txt\\" name=\\"cat\\">"]}'),
(1384,'html','Hard','Input type #5','<input type="txt" name="lake">','The type for text is text.','HTML:{"has": ["<input type=\\"text\\" name=\\"lake\\">"], "not": ["<input type=\\"txt\\" name=\\"lake\\">"]}'),
(1385,'html','Hard','Label and id #1','<label for="star">Name</label>\n<input name="star">','A label for must match an id.','HTML:{"has": ["<input id=\\"star\\">"], "not": ["<input name=\\"star\\">"]}'),
(1386,'html','Hard','Label and id #2','<label for="book">Name</label>\n<input name="book">','A label for must match an id.','HTML:{"has": ["<input id=\\"book\\">"], "not": ["<input name=\\"book\\">"]}'),
(1387,'html','Hard','Label and id #3','<label for="fish">Name</label>\n<input name="fish">','A label for must match an id.','HTML:{"has": ["<input id=\\"fish\\">"], "not": ["<input name=\\"fish\\">"]}'),
(1388,'html','Hard','Label and id #4','<label for="bird">Name</label>\n<input name="bird">','A label for must match an id.','HTML:{"has": ["<input id=\\"bird\\">"], "not": ["<input name=\\"bird\\">"]}'),
(1389,'html','Hard','Label and id #5','<label for="sun">Name</label>\n<input name="sun">','A label for must match an id.','HTML:{"has": ["<input id=\\"sun\\">"], "not": ["<input name=\\"sun\\">"]}'),
(1390,'html','Hard','Select option #1','<select>\n  <opt>moon</option>\n</select>','Choices use option.','HTML:{"has": ["<option>moon</option>"], "not": ["<opt>moon</option>"]}'),
(1391,'html','Hard','Select option #2','<select>\n  <opt>tree</option>\n</select>','Choices use option.','HTML:{"has": ["<option>tree</option>"], "not": ["<opt>tree</option>"]}'),
(1392,'html','Hard','Select option #3','<select>\n  <opt>sun</option>\n</select>','Choices use option.','HTML:{"has": ["<option>sun</option>"], "not": ["<opt>sun</option>"]}'),
(1393,'html','Hard','Select option #4','<select>\n  <opt>home</option>\n</select>','Choices use option.','HTML:{"has": ["<option>home</option>"], "not": ["<opt>home</option>"]}'),
(1394,'html','Hard','Select option #5','<select>\n  <opt>book</option>\n</select>','Choices use option.','HTML:{"has": ["<option>book</option>"], "not": ["<opt>book</option>"]}'),
(1395,'html','Hard','Box shadow #1','.card { boxshadow: 0 2px 8px orange; }','The property has a dash.','HTML:{"has": [".card { box-shadow: 0 2px 8px orange; }"], "not": [".card { boxshadow: 0 2px 8px orange; }"]}'),
(1396,'html','Hard','Box shadow #2','.card { boxshadow: 0 2px 24px orange; }','The property has a dash.','HTML:{"has": [".card { box-shadow: 0 2px 24px orange; }"], "not": [".card { boxshadow: 0 2px 24px orange; }"]}'),
(1397,'html','Hard','Box shadow #3','.card { boxshadow: 0 2px 24px gray; }','The property has a dash.','HTML:{"has": [".card { box-shadow: 0 2px 24px gray; }"], "not": [".card { boxshadow: 0 2px 24px gray; }"]}'),
(1398,'html','Hard','Box shadow #4','.card { boxshadow: 0 2px 28px pink; }','The property has a dash.','HTML:{"has": [".card { box-shadow: 0 2px 28px pink; }"], "not": [".card { boxshadow: 0 2px 28px pink; }"]}'),
(1399,'html','Hard','Box shadow #5','.card { boxshadow: 0 2px 24px blue; }','The property has a dash.','HTML:{"has": [".card { box-shadow: 0 2px 24px blue; }"], "not": [".card { boxshadow: 0 2px 24px blue; }"]}'),
(1400,'html','Hard','Hover state #1','a:over { color: orange; }','The pseudo-class is hover.','HTML:{"has": ["a:hover { color: orange; }"], "not": ["a:over { color: orange; }"]}');
INSERT INTO `new_challenges`(id,language,level,title,buggy_code,hint,expected_output) VALUES
(1401,'html','Hard','Hover state #2','a:over { color: purple; }','The pseudo-class is hover.','HTML:{"has": ["a:hover { color: purple; }"], "not": ["a:over { color: purple; }"]}'),
(1402,'html','Hard','Hover state #3','a:over { color: red; }','The pseudo-class is hover.','HTML:{"has": ["a:hover { color: red; }"], "not": ["a:over { color: red; }"]}'),
(1403,'html','Hard','Hover state #4','a:over { color: pink; }','The pseudo-class is hover.','HTML:{"has": ["a:hover { color: pink; }"], "not": ["a:over { color: pink; }"]}'),
(1404,'html','Hard','Hover state #5','a:over { color: blue; }','The pseudo-class is hover.','HTML:{"has": ["a:hover { color: blue; }"], "not": ["a:over { color: blue; }"]}'),
(1405,'html','Hard','Sticky menu #1','.menu { position: stick; top: 0; }','The value is sticky.','HTML:{"has": [".menu { position: sticky; top: 0; }"], "not": [".menu { position: stick; top: 0; }"]}'),
(1406,'html','Hard','Form method #1','<form action="/send" method="pots">','The method is post.','HTML:{"has": ["<form action=\\"/send\\" method=\\"post\\">"], "not": ["<form action=\\"/send\\" method=\\"pots\\">"]}'),
(1407,'html','Advanced','Media query #1','@media (max_width: 600px) { body { background: red; } }','The feature is max-width.','HTML:{"has": ["@media (max-width: 600px) { body { background: red; } }"], "not": ["@media (max_width: 600px) { body { background: red; } }"]}'),
(1408,'html','Advanced','Media query #2','@media (max_width: 600px) { body { background: green; } }','The feature is max-width.','HTML:{"has": ["@media (max-width: 600px) { body { background: green; } }"], "not": ["@media (max_width: 600px) { body { background: green; } }"]}'),
(1409,'html','Advanced','Media query #3','@media (max_width: 600px) { body { background: brown; } }','The feature is max-width.','HTML:{"has": ["@media (max-width: 600px) { body { background: brown; } }"], "not": ["@media (max_width: 600px) { body { background: brown; } }"]}'),
(1410,'html','Advanced','Media query #4','@media (max_width: 600px) { body { background: blue; } }','The feature is max-width.','HTML:{"has": ["@media (max-width: 600px) { body { background: blue; } }"], "not": ["@media (max_width: 600px) { body { background: blue; } }"]}'),
(1411,'html','Advanced','Media query #5','@media (max_width: 600px) { body { background: orange; } }','The feature is max-width.','HTML:{"has": ["@media (max-width: 600px) { body { background: orange; } }"], "not": ["@media (max_width: 600px) { body { background: orange; } }"]}'),
(1412,'html','Advanced','CSS variable #1',':root { -color: teal; }','Variables start with two dashes.','HTML:{"has": [":root { --color: teal; }"], "not": [":root { -color: teal; }"]}'),
(1413,'html','Advanced','CSS variable #2',':root { -color: gray; }','Variables start with two dashes.','HTML:{"has": [":root { --color: gray; }"], "not": [":root { -color: gray; }"]}'),
(1414,'html','Advanced','CSS variable #3',':root { -color: green; }','Variables start with two dashes.','HTML:{"has": [":root { --color: green; }"], "not": [":root { -color: green; }"]}'),
(1415,'html','Advanced','CSS variable #4',':root { -color: blue; }','Variables start with two dashes.','HTML:{"has": [":root { --color: blue; }"], "not": [":root { -color: blue; }"]}'),
(1416,'html','Advanced','CSS variable #5',':root { -color: pink; }','Variables start with two dashes.','HTML:{"has": [":root { --color: pink; }"], "not": [":root { -color: pink; }"]}'),
(1417,'html','Advanced','Use a variable #1','p { color: var(color); }','Use var with the two dashes.','HTML:{"has": ["p { color: var(--color); }"], "not": ["p { color: var(color); }"]}'),
(1418,'html','Advanced','Semantic nav #1','<header>\n  <div><a href="#">Home</a></nav>\n</header>','Navigation links belong in nav.','HTML:{"has": ["<nav><a href=\\"#\\">Home</a></nav>"], "not": ["<div><a href=\\"#\\">Home</a></nav>"]}'),
(1419,'html','Advanced','Lazy loading #1','<img src="moon.png" alt="moon" loading=lazy>','Attribute values need quotes.','HTML:{"has": ["<img src=\\"moon.png\\" alt=\\"moon\\" loading=\\"lazy\\">"], "not": ["<img src=\\"moon.png\\" alt=\\"moon\\" loading=lazy>"]}'),
(1420,'html','Advanced','Lazy loading #2','<img src="bird.png" alt="bird" loading=lazy>','Attribute values need quotes.','HTML:{"has": ["<img src=\\"bird.png\\" alt=\\"bird\\" loading=\\"lazy\\">"], "not": ["<img src=\\"bird.png\\" alt=\\"bird\\" loading=lazy>"]}'),
(1421,'html','Advanced','Lazy loading #3','<img src="lake.png" alt="lake" loading=lazy>','Attribute values need quotes.','HTML:{"has": ["<img src=\\"lake.png\\" alt=\\"lake\\" loading=\\"lazy\\">"], "not": ["<img src=\\"lake.png\\" alt=\\"lake\\" loading=lazy>"]}'),
(1422,'html','Advanced','Lazy loading #4','<img src="fish.png" alt="fish" loading=lazy>','Attribute values need quotes.','HTML:{"has": ["<img src=\\"fish.png\\" alt=\\"fish\\" loading=\\"lazy\\">"], "not": ["<img src=\\"fish.png\\" alt=\\"fish\\" loading=lazy>"]}'),
(1423,'html','Advanced','Lazy loading #5','<img src="book.png" alt="book" loading=lazy>','Attribute values need quotes.','HTML:{"has": ["<img src=\\"book.png\\" alt=\\"book\\" loading=\\"lazy\\">"], "not": ["<img src=\\"book.png\\" alt=\\"book\\" loading=lazy>"]}'),
(1424,'html','Advanced','Focus style #1','button:focus-visibel { outline: 2px solid red; }','The pseudo-class is focus-visible.','HTML:{"has": ["button:focus-visible { outline: 2px solid red; }"], "not": ["button:focus-visibel { outline: 2px solid red; }"]}'),
(1425,'html','Advanced','Focus style #2','button:focus-visibel { outline: 2px solid teal; }','The pseudo-class is focus-visible.','HTML:{"has": ["button:focus-visible { outline: 2px solid teal; }"], "not": ["button:focus-visibel { outline: 2px solid teal; }"]}'),
(1426,'html','Advanced','Focus style #3','button:focus-visibel { outline: 2px solid gray; }','The pseudo-class is focus-visible.','HTML:{"has": ["button:focus-visible { outline: 2px solid gray; }"], "not": ["button:focus-visibel { outline: 2px solid gray; }"]}'),
(1427,'html','Advanced','Focus style #4','button:focus-visibel { outline: 2px solid orange; }','The pseudo-class is focus-visible.','HTML:{"has": ["button:focus-visible { outline: 2px solid orange; }"], "not": ["button:focus-visibel { outline: 2px solid orange; }"]}'),
(1428,'html','Advanced','Focus style #5','button:focus-visibel { outline: 2px solid brown; }','The pseudo-class is focus-visible.','HTML:{"has": ["button:focus-visible { outline: 2px solid brown; }"], "not": ["button:focus-visibel { outline: 2px solid brown; }"]}'),
(1429,'html','Advanced','ARIA label #1','<button aria-lable="Close">X</button>','The attribute is aria-label.','HTML:{"has": ["<button aria-label=\\"Close\\">X</button>"], "not": ["<button aria-lable=\\"Close\\">X</button>"]}'),
(1430,'html','Advanced','Transition time #1','.box { transition: all 0.3 ease; }','A time needs a unit.','HTML:{"has": [".box { transition: all 0.3s ease; }"], "not": [".box { transition: all 0.3 ease; }"]}'),
(1431,'html','Advanced','Keyframes name #1','@keyframes slide in { from { opacity: 0; } to { opacity: 1; } }','Names use dashes, not spaces.','HTML:{"has": ["@keyframes slide-in { from { opacity: 0; } to { opacity: 1; } }"], "not": ["@keyframes slide in { from { opacity: 0; } to { opacity: 1; } }"]}'),
(1432,'html','Advanced','Clamp function #1','.title { font-size: clamp(1rem 2vw 2rem); }','Separate values with commas.','HTML:{"has": [".title { font-size: clamp(1rem, 2vw, 2rem); }"], "not": [".title { font-size: clamp(1rem 2vw 2rem); }"]}'),
(1433,'html','Medium','Link target','<a href="https://example.com" target="blank">Visit</a>','The value that opens a new tab starts with an underscore.','HTML:{"has": ["target=\\"_blank\\""], "not": ["target=\\"blank\\""]}'),
(1434,'html','Medium','Image alt text','<img src="cat.png" altt="A cat">','The attribute for the picture description is spelled alt.','HTML:{"has": ["alt=\\"A cat\\""], "not": ["altt=\\"A cat\\""]}'),
(1435,'html','Medium','Ordered list','<ol><li>One</li><li>Two</li></ul>','Close the list with the same kind of tag you opened.','HTML:{"has": ["<li>Two</li></ol>"], "not": ["<li>Two</li></ul>"]}'),
(1436,'html','Medium','Table cell','<table><tr><td>Ana</tr></table>','A cell must be closed with its own tag.','HTML:{"has": ["<td>Ana</td>"], "not": ["<td>Ana</tr>"]}'),
(1437,'html','Medium','Comment syntax','<!- This is a comment ->','An HTML comment starts with two dashes and ends with two dashes.','HTML:{"has": ["<!-- This is a comment -->"], "not": ["<!- This is a comment ->"]}'),
(1438,'html','Medium','Line break','<p>Line one</br>Line two</p>','The line break tag has no closing tag. It is just br.','HTML:{"has": ["Line one<br>Line two"], "not": ["Line one</br>Line two"]}'),
(1439,'html','Medium','Text decoration','h1 { text-decoration: underlined; }','The value is underline.','HTML:{"has": ["text-decoration: underline;"], "not": ["text-decoration: underlined"]}'),
(1440,'html','Medium','Padding spelling','div { pading: 10px; }','Check how padding is spelled.','HTML:{"has": ["padding: 10px"], "not": ["pading: 10px"]}');
INSERT INTO `new_challenges`(id,language,level,title,buggy_code,hint,expected_output) VALUES
(1441,'html','Hard','Viewport meta','<meta name="viewport" content="width=device-width initial-scale=1">','Separate the two settings with a comma.','HTML:{"has": ["width=device-width, initial-scale=1"], "not": ["width=device-width initial-scale=1"]}'),
(1442,'html','Hard','Doctype line','<!DOCTYPE>\n<html><body>Hi</body></html>','The doctype needs the word html after it.','HTML:{"has": ["<!DOCTYPE html>"], "not": ["<!DOCTYPE>"]}'),
(1443,'html','Hard','Stylesheet link','<link rel="stylesheets" href="style.css">','The rel value is singular.','HTML:{"has": ["rel=\\"stylesheet\\""], "not": ["rel=\\"stylesheets\\""]}'),
(1444,'html','Hard','Script file','<script href="app.js"></script>','A script file is loaded with src, not href.','HTML:{"has": ["<script src=\\"app.js\\">"], "not": ["<script href=\\"app.js\\">"]}'),
(1445,'html','Hard','Submit button','<form><button type="sumbit">Send</button></form>','Check the spelling of submit.','HTML:{"has": ["type=\\"submit\\""], "not": ["type=\\"sumbit\\""]}'),
(1446,'html','Hard','Checkbox type','<input type="check box">','The type is one word.','HTML:{"has": ["type=\\"checkbox\\""], "not": ["type=\\"check box\\""]}'),
(1447,'html','Hard','Textarea closing','<textarea rows="3" cols="30"/>','Textarea needs a real closing tag.','HTML:{"has": ["<textarea rows=\\"3\\" cols=\\"30\\"></textarea>"], "not": ["<textarea rows=\\"3\\" cols=\\"30\\"/>"]}'),
(1448,'html','Hard','Placeholder spelling','<input type="text" placehoder="Name">','The attribute is placeholder.','HTML:{"has": ["placeholder=\\"Name\\""], "not": ["placehoder=\\"Name\\""]}'),
(1449,'html','Hard','Relative position','.box { position: relatve; }','Check the spelling of relative.','HTML:{"has": ["position: relative;"], "not": ["position: relatve"]}'),
(1450,'html','Hard','Z-index value','.menu { z-index: high; }','z-index needs a number.','HTML:{"has": ["z-index: 10"], "not": ["z-index: high"]}'),
(1451,'html','Hard','Overflow scroll','.box { overflow: scrol; }','The value is scroll.','HTML:{"has": ["overflow: scroll;"], "not": ["overflow: scrol;"]}'),
(1452,'html','Hard','Grid gap unit','.grid { display: grid; grid-gap: 10; }','Lengths need a unit such as px.','HTML:{"has": ["grid-gap: 10px"], "not": ["grid-gap: 10;"]}'),
(1453,'html','Hard','Flex direction','.row { display: flex; flex-direction: columns; }','The value is column, not columns.','HTML:{"has": ["flex-direction: column;"], "not": ["flex-direction: columns"]}'),
(1454,'html','Hard','Spread items','.row { display: flex; justify-content: center-space; }','The value that pushes items to both ends is space-between.','HTML:{"has": ["justify-content: space-between"], "not": ["justify-content: center-space"]}'),
(1455,'html','Hard','Opacity decimal','.img { opacity: 0,5; }','Decimals use a dot, not a comma.','HTML:{"has": ["opacity: 0.5"], "not": ["opacity: 0,5"]}'),
(1456,'html','Hard','Radius unit','.card { border-radius: 10 px; }','Do not leave a space between 10 and px.','HTML:{"has": ["border-radius: 10px"], "not": ["border-radius: 10 px"]}'),
(1457,'html','Advanced','Before pseudo-element','p::befor { content: "*"; }','Check the spelling of before.','HTML:{"has": ["p::before"], "not": ["p::befor"]}'),
(1458,'html','Advanced','nth-child bracket','li:nth-child(odd { color: red; }','Close the bracket after odd.','HTML:{"has": ["li:nth-child(odd)"], "not": ["li:nth-child(odd {"]}'),
(1459,'html','Advanced','Grid template columns','.grid { display: grid; grid-template-column: 1fr 1fr; }','The property name ends with an s.','HTML:{"has": ["grid-template-columns: 1fr 1fr"], "not": ["grid-template-column: 1fr 1fr"]}'),
(1460,'html','Advanced','Calc spacing','.box { width: calc(100%-20px); }','Put spaces around the minus sign inside calc.','HTML:{"has": ["calc(100% - 20px)"], "not": ["calc(100%-20px)"]}'),
(1461,'html','Advanced','rgba alpha','.box { color: rgba(0, 0, 0, 50); }','Alpha goes from 0 to 1.','HTML:{"has": ["rgba(0, 0, 0, 0.5)"], "not": ["rgba(0, 0, 0, 50)"]}'),
(1462,'html','Advanced','Important flag','p { color: red !importnat; }','Check the spelling of important.','HTML:{"has": ["!important"], "not": ["!importnat"]}'),
(1463,'html','Advanced','Attribute selector','input[type=text { border: 1px solid; }','Close the square bracket and quote the value.','HTML:{"has": ["input[type=\\"text\\"]"], "not": ["input[type=text {"]}'),
(1464,'html','Advanced','Rotate unit','.box { transform: rotate(45); }','Angles need the unit deg.','HTML:{"has": ["rotate(45deg)"], "not": ["rotate(45)"]}'),
(1465,'html','Advanced','Transition seconds','a { transition: color 0.3 ease; }','Time needs the unit s.','HTML:{"has": ["0.3s ease"], "not": ["0.3 ease"]}'),
(1466,'html','Advanced','Animation infinite','.dot { animation: pulse 2s infinit; }','Check the spelling of infinite.','HTML:{"has": ["animation: pulse 2s infinite;"], "not": ["infinit;"]}'),
(1467,'html','Advanced','Keyframe percent','@keyframes grow { 0% { width: 0; } 100 { width: 100px; } }','Keyframe steps use the percent sign.','HTML:{"has": ["100% { width: 100px; }"], "not": ["100 { width: 100px; }"]}'),
(1468,'html','Advanced','Custom property name','.theme { color-main: blue; }\n.theme p { color: var(--color-main); }','Custom properties begin with two dashes.','HTML:{"has": ["--color-main: blue"], "not": ["{ color-main: blue"]}'),
(1469,'html','Advanced','Video closing tag','<video controls src="movie.mp4"/>','Video needs a real closing tag.','HTML:{"has": ["<video controls src=\\"movie.mp4\\"></video>"], "not": ["<video controls src=\\"movie.mp4\\"/>"]}'),
(1470,'html','Advanced','Iframe width','<iframe src="page.html" widht="300"></iframe>','Check the spelling of width.','HTML:{"has": ["width=\\"300\\""], "not": ["widht=\\"300\\""]}'),
(1471,'html','Advanced','Charset name','<meta charset="utf8">','The usual name has a dash.','HTML:{"has": ["charset=\\"utf-8\\""], "not": ["charset=\\"utf8\\""]}'),
(1472,'html','Advanced','Language attribute','<html lan="en">','The attribute is lang.','HTML:{"has": ["<html lang=\\"en\\">"], "not": ["<html lan=\\"en\\">"]}'),
(1473,'html','Advanced','Section closing tag','<section><h2>Title</h2></sectoin>','Check how section is spelled in the closing tag.','HTML:{"has": ["</section>"], "not": ["</sectoin>"]}'),
(1474,'html','Advanced','Figure caption','<figure><img src="a.png" alt="A"><figcaption>Caption</figcation></figure>','Check the closing figcaption tag.','HTML:{"has": ["</figcaption>"], "not": ["</figcation>"]}'),
(1475,'html','Advanced','Details closing tag','<details><summary>More</summary><p>Text</p></detail>','The closing tag matches the opening tag: details.','HTML:{"has": ["</details>"], "not": ["</detail>"]}'),
(1476,'html','Advanced','Media query colon','@media (min-width 600px) { p { color: red; } }','A feature and its value are separated by a colon.','HTML:{"has": ["(min-width: 600px)"], "not": ["(min-width 600px)"]}'),
(1477,'html','Advanced','Font family list','body { font-family: Arial sans-serif; }','Separate font names with a comma.','HTML:{"has": ["font-family: Arial, sans-serif"], "not": ["font-family: Arial sans-serif"]}'),
(1478,'html','Advanced','Visited link','a:visted { color: purple; }','Check the spelling of visited.','HTML:{"has": ["a:visited"], "not": ["a:visted"]}'),
(1479,'html','Advanced','Selector list','h1, h2 h3 { color: navy; }','Separate every selector with a comma.','HTML:{"has": ["h1, h2, h3"], "not": ["h1, h2 h3"]}'),
(1480,'html','Advanced','Aspect ratio','.video { aspect-ratio: 16 9; }','Use a slash between the two numbers.','HTML:{"has": ["aspect-ratio: 16 / 9"], "not": ["aspect-ratio: 16 9"]}');
INSERT INTO `challenges`(id,language,level,title,buggy_code,hint,expected_output) SELECT n.id,n.language,n.level,n.title,n.buggy_code,n.hint,n.expected_output FROM `new_challenges` n WHERE NOT EXISTS (SELECT 1 FROM `challenges`);
