-- =====================================================================
-- CodeSmartAi-X  -  database (VERSION 48, the latest). SAFE: it never deletes anybody's data.
--
-- What it does:
--   * makes the database capstone_db if it is not there yet
--   * makes every table that is missing (25 tables, only the columns version 48 uses)
--   * fills the lessons (24 modules, 1200 lessons) and the challenges (200 for each of the 6 languages)
--     ONLY when those tables are empty. A database that already has them is not changed.
--   * removes only 2 tables that nothing uses any more: schema_migrations and enrolled_ids
--   It does NOT drop or empty any table with accounts, classes, quizzes, code exams, grades or the email setup.
--   So it is safe to import again, also into a database that is already in use.
--
-- A database that is already in use does not need this file at all: the website updates it by itself
-- (database/schema.php) the first time a page opens, and removes the old columns that are not used any more.
-- Lessons without text are written by the AI the first time somebody opens them, and then saved.
--
-- HOW TO USE (phpMyAdmin):
--   1. Start Apache and MySQL (or double-click the CodeSmartAI-X desktop icon). Open http://localhost/phpmyadmin
--   2. Click the Import tab at the top (no need to click a database first).
--   3. Choose this file and press Import.
--   4. Open the website. The first page that opens makes the ONE admin account if there is none:
--        Login ID: admin     First password: Admin-Start-2026   (config.php ADMIN_ID / ADMIN_START_PASSWORD)
--      Then set up Admin > Email (Gmail + App password) so the login, sign-up and password codes are emailed.
-- To move a database WITH students and grades to another computer, use Export in phpMyAdmin.
-- =====================================================================
SET NAMES utf8mb4;
CREATE DATABASE IF NOT EXISTS `capstone_db` CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci;
USE `capstone_db`;
SET FOREIGN_KEY_CHECKS=0;

-- ---------- the 25 tables (made only when missing) ----------
CREATE TABLE IF NOT EXISTS `users`(id INT AUTO_INCREMENT PRIMARY KEY, full_name VARCHAR(100) NOT NULL, student_id VARCHAR(30) NULL UNIQUE, year_level TINYINT NULL, email VARCHAR(120) NOT NULL UNIQUE, password_hash VARCHAR(255) NOT NULL, role ENUM('student','teacher','admin') NOT NULL DEFAULT 'student', created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, email_verified TINYINT NOT NULL DEFAULT 1, approved TINYINT NOT NULL DEFAULT 1, approved_by INT NULL, approved_at DATETIME NULL) DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS `classes`(id INT AUTO_INCREMENT PRIMARY KEY, teacher_id INT NOT NULL, name VARCHAR(100) NOT NULL, section VARCHAR(40) NOT NULL DEFAULT '', year_level TINYINT NULL, join_code VARCHAR(10) NOT NULL UNIQUE, school_year VARCHAR(9) NULL, archived TINYINT NOT NULL DEFAULT 0, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(teacher_id) REFERENCES users(id) ON DELETE CASCADE) DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS `class_members`(class_id INT NOT NULL, student_id INT NOT NULL, joined_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, PRIMARY KEY(class_id,student_id), INDEX idx_member(student_id), FOREIGN KEY(class_id) REFERENCES classes(id) ON DELETE CASCADE, FOREIGN KEY(student_id) REFERENCES users(id) ON DELETE CASCADE) DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS `quizzes`(id INT AUTO_INCREMENT PRIMARY KEY, teacher_id INT NOT NULL, title VARCHAR(150) NOT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, show_answers TINYINT NOT NULL DEFAULT 1, closed TINYINT NOT NULL DEFAULT 0, school_year VARCHAR(9) NULL, class_id INT NULL, opens_at DATETIME NULL, due_at DATETIME NULL, INDEX idx_class(class_id), FOREIGN KEY(teacher_id) REFERENCES users(id) ON DELETE CASCADE) DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS `questions`(id INT AUTO_INCREMENT PRIMARY KEY, quiz_id INT NOT NULL, question TEXT NOT NULL, opt_a VARCHAR(255) NOT NULL, opt_b VARCHAR(255) NOT NULL, opt_c VARCHAR(255) NOT NULL, opt_d VARCHAR(255) NOT NULL, correct CHAR(1) NOT NULL, FOREIGN KEY(quiz_id) REFERENCES quizzes(id) ON DELETE CASCADE) DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS `attempts`(id INT AUTO_INCREMENT PRIMARY KEY, quiz_id INT NOT NULL, student_id INT NOT NULL, score INT DEFAULT 0, total INT DEFAULT 0, started_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, submitted_at DATETIME NULL, year_level TINYINT NULL, UNIQUE(quiz_id,student_id), FOREIGN KEY(quiz_id) REFERENCES quizzes(id) ON DELETE CASCADE, FOREIGN KEY(student_id) REFERENCES users(id) ON DELETE CASCADE) DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS `quiz_answers`(attempt_id INT NOT NULL, question_id INT NOT NULL, choice CHAR(1) NOT NULL, PRIMARY KEY(attempt_id,question_id), FOREIGN KEY(attempt_id) REFERENCES attempts(id) ON DELETE CASCADE, FOREIGN KEY(question_id) REFERENCES questions(id) ON DELETE CASCADE) DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS `cheat_events`(id INT AUTO_INCREMENT PRIMARY KEY, attempt_id INT NOT NULL, event_type VARCHAR(30) NOT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(attempt_id) REFERENCES attempts(id) ON DELETE CASCADE) DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS `coding_exams`(id INT AUTO_INCREMENT PRIMARY KEY, teacher_id INT NOT NULL, title VARCHAR(150) NOT NULL, language VARCHAR(20) NOT NULL, prompt TEXT NOT NULL, expected_output VARCHAR(255) NOT NULL, minutes INT NOT NULL DEFAULT 30, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, max_points INT NOT NULL DEFAULT 100, closed TINYINT NOT NULL DEFAULT 0, school_year VARCHAR(9) NULL, class_id INT NULL, opens_at DATETIME NULL, due_at DATETIME NULL, starter MEDIUMTEXT NULL, attachment VARCHAR(80) NULL, attachment_check VARCHAR(20) NULL, INDEX idx_class(class_id), FOREIGN KEY(teacher_id) REFERENCES users(id) ON DELETE CASCADE) DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS `exam_attempts`(id INT AUTO_INCREMENT PRIMARY KEY, exam_id INT NOT NULL, student_id INT NOT NULL, code MEDIUMTEXT, output TEXT, passed TINYINT NOT NULL DEFAULT 0, started_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, submitted_at DATETIME NULL, score INT NULL, feedback VARCHAR(500) NULL, graded_at DATETIME NULL, year_level TINYINT NULL, UNIQUE(exam_id,student_id), FOREIGN KEY(exam_id) REFERENCES coding_exams(id) ON DELETE CASCADE, FOREIGN KEY(student_id) REFERENCES users(id) ON DELETE CASCADE) DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS `exam_events`(id INT AUTO_INCREMENT PRIMARY KEY, attempt_id INT NOT NULL, event_type VARCHAR(30) NOT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(attempt_id) REFERENCES exam_attempts(id) ON DELETE CASCADE) DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS `modules`(id INT AUTO_INCREMENT PRIMARY KEY, language VARCHAR(20) NOT NULL, title VARCHAR(100) NOT NULL, level VARCHAR(20) NOT NULL, summary VARCHAR(255) NOT NULL) DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS `lessons`(id INT AUTO_INCREMENT PRIMARY KEY, module_id INT NOT NULL, position INT NOT NULL, title VARCHAR(100) NOT NULL, body TEXT NULL, UNIQUE KEY uq_lesson (module_id, position), FOREIGN KEY(module_id) REFERENCES modules(id) ON DELETE CASCADE) DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS `challenges`(id INT AUTO_INCREMENT PRIMARY KEY, language VARCHAR(20) NOT NULL, level VARCHAR(10) NOT NULL DEFAULT 'Easy', title VARCHAR(100) NOT NULL, buggy_code TEXT NOT NULL, hint VARCHAR(255) NOT NULL, expected_output VARCHAR(255) NOT NULL) DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS `challenge_solves`(user_id INT NOT NULL, challenge_id INT NOT NULL, solved_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, PRIMARY KEY(user_id,challenge_id), FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE, FOREIGN KEY(challenge_id) REFERENCES challenges(id) ON DELETE CASCADE) DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS `saved_work`(user_id INT NOT NULL, slot VARCHAR(30) NOT NULL, code MEDIUMTEXT, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, PRIMARY KEY(user_id,slot), FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE) DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS `saved_files`(id INT AUTO_INCREMENT PRIMARY KEY, user_id INT NOT NULL, name VARCHAR(80) NOT NULL, language VARCHAR(20) NOT NULL, code MEDIUMTEXT, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, UNIQUE KEY uq_file(user_id,name), FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE) DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS `notifications`(id INT AUTO_INCREMENT PRIMARY KEY, user_id INT NOT NULL, kind VARCHAR(20) NOT NULL, message VARCHAR(255) NOT NULL, link VARCHAR(120) NOT NULL DEFAULT '', shown TINYINT NOT NULL DEFAULT 0, read_at DATETIME NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE) DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS `email_codes`(user_id INT NOT NULL PRIMARY KEY, code_hash CHAR(64) NOT NULL, sent_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE) DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS `login_attempts`(id INT AUTO_INCREMENT PRIMARY KEY, kind VARCHAR(10) NOT NULL, who VARCHAR(100) NOT NULL, tried_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, INDEX idx_who(kind,who,tried_at)) DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS `ai_usage`(user_id INT NOT NULL, used_on DATE NOT NULL, n INT NOT NULL DEFAULT 0, PRIMARY KEY(user_id,used_on), FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE) DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS `settings`(k VARCHAR(30) PRIMARY KEY, v VARCHAR(100) NOT NULL) DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS `promotions`(id INT AUTO_INCREMENT PRIMARY KEY, from_year VARCHAR(9) NOT NULL, to_year VARCHAR(9) NOT NULL, graduate TINYINT NOT NULL DEFAULT 1, closed_quizzes TEXT NULL, closed_exams TEXT NULL, undone TINYINT NOT NULL DEFAULT 0, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP) DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS `year_log`(id INT AUTO_INCREMENT PRIMARY KEY, promotion_id INT NOT NULL, user_id INT NOT NULL, old_year TINYINT NULL, new_year TINYINT NULL, INDEX idx_promo(promotion_id)) DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS `admin_log`(id INT AUTO_INCREMENT PRIMARY KEY, event VARCHAR(30) NOT NULL, ip VARCHAR(45) NOT NULL, agent VARCHAR(160) NOT NULL DEFAULT '', at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, INDEX idx_at(at)) DEFAULT CHARSET=utf8mb4;

-- ---------- not used any more (they never hold people's data) ----------
DROP TABLE IF EXISTS `schema_migrations`;
DROP TABLE IF EXISTS `enrolled_ids`;

-- ---------- lessons and challenges: first into temporary tables, then copied ONLY into empty tables ----------

-- modules: 24 rows
DROP TEMPORARY TABLE IF EXISTS `new_modules`;
CREATE TEMPORARY TABLE `new_modules`(id INT NOT NULL, language VARCHAR(20) NOT NULL, title VARCHAR(100) NOT NULL, level VARCHAR(20) NOT NULL, summary VARCHAR(255) NOT NULL) DEFAULT CHARSET=utf8mb4;
DROP TEMPORARY TABLE `new_modules`;

-- lessons: 1200 rows
DROP TEMPORARY TABLE IF EXISTS `new_lessons`;
CREATE TEMPORARY TABLE `new_lessons`(id INT NOT NULL, module_id INT NOT NULL, position INT NOT NULL, title VARCHAR(100) NOT NULL, body TEXT NULL) DEFAULT CHARSET=utf8mb4;
DROP TEMPORARY TABLE `new_lessons`;

-- challenges: 1200 rows
DROP TEMPORARY TABLE IF EXISTS `new_challenges`;
CREATE TEMPORARY TABLE `new_challenges`(id INT NOT NULL, language VARCHAR(20) NOT NULL, level VARCHAR(10) NOT NULL, title VARCHAR(100) NOT NULL, buggy_code TEXT NOT NULL, hint VARCHAR(255) NOT NULL, expected_output VARCHAR(255) NOT NULL) DEFAULT CHARSET=utf8mb4;
DROP TEMPORARY TABLE `new_challenges`;

SET FOREIGN_KEY_CHECKS=1;
-- end (version 48)
